blic.client_program_exercise_groups\n    where client_program_workout_id = p_workout_id\n      and (\n        array_length(v_seen_group_ids, 1) is null\n        or not (id = any(v_seen_group_ids))\n      );\n  end if;\n\n  return jsonb_build_object('ok', true, 'workoutId', p_workout_id, 'updatedAt', v_now);\nexception when others then\n  return jsonb_build_object('ok', false, 'error', 'db_error', 'message', SQLERRM);\nend;\n$$;\n\ngrant execute on function public.save_client_workout_diff(uuid, text, uuid, timestamptz, jsonb) to service_role;\n\ncreate or replace function public.create_client_workout_diff(\n  p_coach_email text,\n  p_client_id uuid,\n  p_payload jsonb default '{}'::jsonb\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);\n  v_coach_id uuid;\n  v_program_id uuid;\n  v_workout_id uuid;\n  v_now timestamptz := now();\n  v_workout_date date;\n  v_title text;\n  v_coach_comment text;\n  v_status text := 'planned';\n  v_groups jsonb := '[]'::jsonb;\n  v_exercises jsonb := '[]'::jsonb;\n  v_group jsonb;\n  v_exercise jsonb;\n  v_group_id uuid;\n  v_exercise_id uuid;\n  v_library_exercise_id uuid;\n  v_group_ref text;\n  v_group_fk uuid;\n  v_group_ids jsonb := '{}'::jsonb;\n  v_payload_group_refs text[] := array[]::text[];\n  v_group_index integer := 0;\n  v_exercise_index integer := 0;\n  v_group_sort_order integer;\n  v_exercise_sort_order integer;\n  v_exercise_title text;\n  v_uuid_pattern constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';\n  v_int_pattern constant text := '^-?[0-9]+$';\nbegin\n  if p_client_id is null then\n    return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Client id is required');\n  end if;\n\n  if jsonb_typeof(v_payload) <> 'object' then\n    return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Payload must be an object');\n  end if;\n\n  select id\n    into v_coach_id\n  from public.coach_profiles\n  where lower(email) = lower(trim(coalesce(p_coach_email, '')))\n    and is_active = true;\n\n  if v_coach_id is null then\n    return jsonb_build_object('ok', false, 'error', 'forbidden');\n  end if;\n\n  perform 1\n  from public.coach_clients\n  where coach_id = v_coach_id\n    and client_id = p_client_id\n    and is_active = true;\n\n  if not found then\n    return jsonb_build_object('ok', false, 'error', 'forbidden');\n  end if;\n\n  if nullif(v_payload->>'workoutDate', '') is null then\n    return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Workout date is required');\n  end if;\n\n  begin\n    v_workout_date := (v_payload->>'workoutDate')::date;\n  exception when others then\n    return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Workout date must be a valid date');\n  end;\n\n  v_title := nullif(trim(coalesce(v_payload->>'title', '')), '');\n  if v_title is null then\n    return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Workout title is required');\n  end if;\n\n  v_coach_comment := nullif(trim(coalesce(v_payload->>'coachComment', '')), '');\n\n  if v_payload ? 'status' then\n    v_status := nullif(trim(coalesce(v_payload->>'status', '')), '');\n    if v_status is null then\n      return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Workout status is required');\n    end if;\n  end if;\n\n  if coalesce(jsonb_typeof(v_payload->'groups'), '') <> 'array'\n    or coalesce(jsonb_typeof(v_payload->'exercises'), '') <> 'array' then\n    return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Workout payload must include groups and exercises arrays');\n  end if;\n\n  v_groups := v_payload->'groups';\n  v_exercises := v_payload->'exercises';\n\n  for v_group in select value from jsonb_array_elements(v_groups)\n  loop\n    if jsonb_typeof(v_group) <> 'object' then\n      return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Group payload item must be an object');\n    end if;\n\n    if nullif(v_group->>'id', '') is not null then\n      return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Existing group id is not allowed when creating a workout');\n    end if;\n\n    if nullif(v_group->>'sortOrder', '') is not null and not ((v_group->>'sortOrder') ~ v_int_pattern) then\n      return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Exercise group sortOrder must be an integer');\n    end if;\n\n    v_group_ref := nullif(coalesce(v_group->>'draftId', ''), '');\n    if v_group_ref is null then\n      v_group_ref := 'group-' || v_group_index;\n    end if;\n\n    if v_group_ref = any(v_payload_group_refs) then\n      return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Exercise group references must be unique');\n    end if;\n\n    v_payload_group_refs := array_append(v_payload_group_refs, v_group_ref);\n    v_group_index := v_group_index + 1;\n  end loop;\n\n  for v_exercise in select value from jsonb_array_elements(v_exercises)\n  loop\n    if jsonb_typeof(v_exercise) <> 'object' then\n      return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Exercise payload item must be an object');\n    end if;\n\n    if nullif(v_exercise->>'id', '') is not null then\n      return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Existing exercise id is not allowed when creating a workout');\n    end if;\n\n    if nullif(v_exercise->>'exerciseId', '') is not null and not ((v_exercise->>'exerciseId') ~ v_uuid_pattern) then\n      return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Library exercise id must be a valid UUID');\n    end if;\n\n    if nullif(v_exercise->>'sortOrder', '') is not null and not ((v_exercise->>'sortOrder') ~ v_int_pattern) then\n      return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Exercise sortOrder must be an integer');\n    end if;\n\n    v_exercise_title := nullif(trim(coalesce(v_exercise->>'exerciseTitle', v_exercise->>'title', '')), '');\n    if v_exercise_title is null then\n      return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Exercise title is required');\n    end if;\n\n    v_group_ref := nullif(coalesce(v_exercise->>'groupDraftId', v_exercise->>'groupId', ''), '');\n    if v_group_ref is not null and not (v_group_ref = any(v_payload_group_refs)) then\n      return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Exercise group does not belong to this workout payload');\n    end if;\n  end loop;\n\n  perform pg_advisory_xact_lock(hashtext('active-client-program:' || v_coach_id::text || ':' || p_client_id::text));\n\n  select id\n    into v_program_id\n  from public.client_programs\n  where client_id = p_client_id\n    and coach_id = v_coach_id\n    and status = 'active'\n  order by created_at desc\n  limit 1\n  for update;\n\n  if v_program_id is null then\n    insert into public.client_programs (\n      client_id,\n      coach_id,\n      title,\n      status,\n      start_date\n    )\n    values (\n      p_client_id,\n      v_coach_id,\n      'Индивидуальная программа',\n      'active',\n      v_workout_date\n    )\n    returning id into v_program_id;\n  end if;\n\n  insert into public.client_program_workouts (\n    client_program_id,\n    client_id,\n    coach_id,\n    workout_date,\n    title,\n    coach_comment,\n    status,\n    updated_at\n  )\n  values (\n    v_program_id,\n    p_client_id,\n    v_coach_id,\n    v_workout_date,\n    v_title,\n    v_coach_comment,\n    v_status,\n    v_now\n  )\n  returning id into v_workout_id;\n\n  v_group_index := 0;\n  for v_group in select value from jsonb_array_elements(v_groups)\n  loop\n    v_group_ref := nullif(coalesce(v_group->>'draftId', ''), '');\n    if v_group_ref is null then\n      v_group_ref := 'group-' || v_group_index;\n    end if;\n    v_group_sort_order := coalesce(nullif(v_group->>'sortOrder', '')::integer, v_group_index);\n    v_group_id := null;\n\n    insert into public.client_program_exercise_groups (\n      client_program_workout_id,\n      title,\n      sets,\n      rest,\n      notes,\n      sort_order\n    )\n    values (\n      v_workout_id,\n      coalesce(nullif(trim(coalesce(v_group->>'title', '')), ''), 'Комбо ' || (v_group_index + 1)),\n      nullif(trim(coalesce(v_group->>'sets', '')), ''),\n      nullif(trim(coalesce(v_group->>'rest', '')), ''),\n      nullif(trim(coalesce(v_group->>'notes', '')), ''),\n      v_group_sort_order\n    )\n    returning id into v_group_id;\n\n    v_group_ids := v_group_ids || jsonb_build_object(v_group_ref, v_group_id::text);\n    v_group_index := v_group_index + 1;\n  end loop;\n\n  v_exercise_index := 0;\n  for v_exercise in select value from jsonb_array_elements(v_exercises)\n  loop\n    v_library_exercise_id := nullif(v_exercise->>'exerciseId', '')::uuid;\n    v_exercise_title := nullif(trim(coalesce(v_exercise->>'exerciseTitle', v_exercise->>'title', '')), '');\n    v_exercise_sort_order := coalesce(nullif(v_exercise->>'sortOrder', '')::integer, v_exercise_index);\n    v_group_ref := nullif(coalesce(v_exercise->>'groupDraftId', v_exercise->>'groupId', ''), '');\n    v_group_fk := null;\n    v_exercise_id := null;\n\n    if v_group_ref is not null then\n      v_group_fk := (v_group_ids->>v_group_ref)::uuid;\n    end if;\n\n    insert into public.client_program_exercises (\n      client_program_workout_id,\n      exercise_group_id,\n      exercise_id,\n      exercise_title,\n      sets,\n      reps,\n      rest,\n      tempo,\n      notes,\n      sort_order\n    )\n    values (\n      v_workout_id,\n      v_group_fk,\n      v_library_exercise_id,\n      v_exercise_title,\n      case when v_group_fk is null then nullif(trim(coalesce(v_exercise->>'sets', '')), '') else null end,\n      nullif(trim(coalesce(v_exercise->>'reps', '')), ''),\n      case when v_group_fk is null then nullif(trim(coalesce(v_exercise->>'rest', '')), '') else null end,\n      nullif(trim(coalesce(v_exercise->>'tempo', '')), ''),\n      nullif(trim(coalesce(v_exercise->>'notes', '')), ''),\n      v_exercise_sort_order\n    )\n    returning id into v_exercise_id;\n\n    v_exercise_index := v_exercise_index + 1;\n  end loop;\n\n  return jsonb_build_object('ok', true, 'workoutId', v_workout_id, 'updatedAt', v_now);\nexception when others then\n  return jsonb_build_object('ok', false, 'error', 'db_error', 'message', SQLERRM);\nend;\n$$;\n\ngrant execute on function public.create_client_workout_diff(text, uuid, jsonb) to service_role;"}	runtime_workout_diff_save_rpc	ov.shatvoryan@gmail.com	\N	\N
20260629090230	{"-- Idempotent import of selected program template workouts into a client calendar.\n-- This is the backend primitive for \\"copy selected template workout(s) to dates\\";\n-- legacy full-program assignment can call the same RPC in all-workouts mode.\n\ncreate extension if not exists pgcrypto;\n\nalter table public.client_program_workouts\n  add column if not exists source_program_template_id uuid,\n  add column if not exists source_template_workout_id uuid;\n\nalter table public.client_program_exercise_groups\n  add column if not exists source_template_group_id uuid;\n\nalter table public.client_program_exercises\n  add column if not exists source_template_exercise_id uuid;\n\ndo $$\nbegin\n  if not exists (\n    select 1\n    from pg_constraint c\n    join pg_attribute child_col\n      on child_col.attrelid = c.conrelid\n      and child_col.attnum = any(c.conkey)\n    join pg_attribute parent_col\n      on parent_col.attrelid = c.confrelid\n      and parent_col.attnum = any(c.confkey)\n    where c.contype = 'f'\n      and c.conrelid = 'public.client_program_workouts'::regclass\n      and c.confrelid = 'public.program_templates'::regclass\n      and child_col.attname = 'source_program_template_id'\n      and parent_col.attname = 'id'\n  ) then\n    alter table public.client_program_workouts\n      add constraint client_program_workouts_source_program_template_id_fkey\n      foreign key (source_program_template_id)\n      references public.program_templates(id)\n      on delete set null;\n  end if;\n\n  if not exists (\n    select 1\n    from pg_constraint c\n    join pg_attribute child_col\n      on child_col.attrelid = c.conrelid\n      and child_col.attnum = any(c.conkey)\n    join pg_attribute parent_col\n      on parent_col.attrelid = c.confrelid\n      and parent_col.attnum = any(c.confkey)\n    where c.contype = 'f'\n      and c.conrelid = 'public.client_program_workouts'::regclass\n      and c.confrelid = 'public.program_template_workouts'::regclass\n      and child_col.attname = 'source_template_workout_id'\n      and parent_col.attname = 'id'\n  ) then\n    alter table public.client_program_workouts\n      add constraint client_program_workouts_source_template_workout_id_fkey\n      foreign key (source_template_workout_id)\n      references public.program_template_workouts(id)\n      on delete set null;\n  end if;\n\n  if not exists (\n    select 1\n    from pg_constraint c\n    join pg_attribute child_col\n      on child_col.attrelid = c.conrelid\n      and child_col.attnum = any(c.conkey)\n    join pg_attribute parent_col\n      on parent_col.attrelid = c.confrelid\n      and parent_col.attnum = any(c.confkey)\n    where c.contype = 'f'\n      and c.conrelid = 'public.client_program_exercise_groups'::regclass\n      and c.confrelid = 'public.program_template_exercise_groups'::regclass\n      and child_col.attname = 'source_template_group_id'\n      and parent_col.attname = 'id'\n  ) then\n    alter table public.client_program_exercise_groups\n      add constraint client_program_exercise_groups_source_template_group_id_fkey\n      foreign key (source_template_group_id)\n      references public.program_template_exercise_groups(id)\n      on delete set null;\n  end if;\n\n  if not exists (\n    select 1\n    from pg_constraint c\n    join pg_attribute child_col\n      on child_col.attrelid = c.conrelid\n      and child_col.attnum = any(c.conkey)\n    join pg_attribute parent_col\n      on parent_col.attrelid = c.confrelid\n      and parent_col.attnum = any(c.confkey)\n    where c.contype = 'f'\n      and c.conrelid = 'public.client_program_exercises'::regclass\n      and c.confrelid = 'public.program_template_exercises'::regclass\n      and child_col.attname = 'source_template_exercise_id'\n      and parent_col.attname = 'id'\n  ) then\n    alter table public.client_program_exercises\n      add constraint client_program_exercises_source_template_exercise_id_fkey\n      foreign key (source_template_exercise_id)\n      references public.program_template_exercises(id)\n      on delete set null;\n  end if;\nend;\n$$;\n\ncreate unique index if not exists idx_client_program_workouts_template_import_once\n  on public.client_program_workouts(client_id, coach_id, workout_date, source_template_workout_id)\n  where source_template_workout_id is not null;\n\ncreate index if not exists idx_client_program_workouts_source_template\n  on public.client_program_workouts(source_program_template_id, source_template_workout_id);\n\ncreate index if not exists idx_client_program_exercise_groups_source_template\n  on public.client_program_exercise_groups(source_template_group_id);\n\ncreate index if not exists idx_client_program_exercises_source_template\n  on public.client_program_exercises(source_template_exercise_id);\n\ncreate or replace function public.import_program_template_workouts_to_client_calendar(\n  p_coach_email text,\n  p_client_id uuid,\n  p_program_template_id uuid,\n  p_start_date date default null,\n  p_template_workout_ids uuid[] default null,\n  p_workout_dates jsonb default null\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_coach_id uuid;\n  v_template record;\n  v_program_id uuid;\n  v_now timestamptz := now();\n  v_selected_count integer := 0;\n  v_matching_count integer := 0;\n  v_base_day_number integer := 1;\n  v_workout record;\n  v_workout_date date;\n  v_date_raw text;\n  v_client_workout_id uuid;\n  v_group record;\n  v_exercise record;\n  v_group_id uuid;\n  v_group_id_by_template_id jsonb;\n  v_created_workouts integer := 0;\n  v_reused_workouts integer := 0;\n  v_imported_workouts jsonb := '[]'::jsonb;\nbegin\n  if p_client_id is null then\n    return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Client id is required');\n  end if;\n\n  if p_program_template_id is null then\n    return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Program template id is required');\n  end if;\n\n  if p_start_date is null and (p_workout_dates is null or jsonb_typeof(p_workout_dates) <> 'object') then\n    return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Start date or workout date map is required');\n  end if;\n\n  if p_workout_dates is not null and jsonb_typeof(p_workout_dates) <> 'object' then\n    return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Workout dates must be an object');\n  end if;\n\n  select id\n    into v_coach_id\n  from public.coach_profiles\n  where lower(email) = lower(trim(coalesce(p_coach_email, '')))\n    and is_active = true;\n\n  if v_coach_id is null then\n    return jsonb_build_object('ok', false, 'error', 'forbidden');\n  end if;\n\n  perform 1\n  from public.coach_clients\n  where coach_id = v_coach_id\n    and client_id = p_client_id\n    and is_active = true;\n\n  if not found then\n    return jsonb_build_object('ok', false, 'error', 'forbidden');\n  end if;\n\n  select *\n    into v_template\n  from public.program_templates\n  where id = p_program_template_id\n    and is_active = true\n  for update;\n\n  if not found then\n    return jsonb_build_object('ok', false, 'error', 'not_found');\n  end if;\n\n  if v_template.coach_id is not null and v_template.coach_id <> v_coach_id then\n    return jsonb_build_object('ok', false, 'error', 'not_found');\n  end if;\n\n  perform pg_advisory_xact_lock(\n    hashtext('template-workout-import:' || v_coach_id::text || ':' || p_client_id::text || ':' || p_program_template_id::text)\n  );\n\n  if array_length(p_template_workout_ids, 1) is not null then\n    select count(distinct workout_id)\n      into v_selected_count\n    from unnest(p_template_workout_ids) as selected(workout_id);\n\n    select count(*)\n      into v_matching_count\n    from public.program_template_workouts\n    where program_template_id = p_program_template_id\n      and id = any(p_template_workout_ids);\n\n    if v_selected_count <> v_matching_count then\n      return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Selected workout does not belong to program template');\n    end if;\n  end if;\n\n  select coalesce(min(day_number), 1)\n    into v_base_day_number\n  from public.program_template_workouts\n  where program_template_id = p_program_template_id\n    and (\n      array_length(p_template_workout_ids, 1) is null\n      or id = any(p_template_workout_ids)\n    );\n\n  select id\n    into v_program_id\n  from public.client_programs\n  where client_id = p_client_id\n    and coach_id = v_coach_id\n    and status = 'active'\n  order by created_at desc\n  limit 1\n  for update;\n\n  if v_program_id is null then\n    insert into public.client_programs (\n      client_id,\n      coach_id,\n      title,\n      status,\n      start_date\n    )\n    values (\n      p_client_id,\n      v_coach_id,\n      coalesce(nullif(trim(v_template.title), ''), 'Индивидуальная программа'),\n      'active',\n      coalesce(p_start_date, current_date)\n    )\n    returning id into v_program_id;\n  end if;\n\n  for v_workout in\n    select *\n    from public.program_template_workouts\n    where program_template_id = p_program_template_id\n      and (\n        array_length(p_template_workout_ids, 1) is null\n        or id = any(p_template_workout_ids)\n      )\n    order by sort_order, day_number, title\n  loop\n    v_date_raw := null;\n    if p_workout_dates is not null then\n      v_date_raw := nullif(p_workout_dates->>v_workout.id::text, '');\n    end if;\n\n    begin\n      v_workout_date := coalesce(\n        v_date_raw::date,\n        p_start_date + greatest(coalesce(v_workout.day_number, v_base_day_number) - v_base_day_number, 0)\n      );\n    exception when others then\n      return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Workout date must be a valid date');\n    end;\n\n    if v_workout_date is null then\n      return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Workout date is required');\n    end if;\n\n    select id\n      into v_client_workout_id\n    from public.client_program_workouts\n    where client_id = p_client_id\n      and coach_id = v_coach_id\n      and workout_date = v_workout_date\n      and source_template_workout_id = v_workout.id\n    limit 1\n    for update;\n\n    if v_client_workout_id is not null then\n      v_reused_workouts := v_reused_workouts + 1;\n      v_imported_workouts := v_imported_workouts || jsonb_build_array(\n        jsonb_build_object(\n          'workoutDate', v_workout_date,\n          'sourceTemplateWorkoutId', v_workout.id,\n          'clientWorkoutId', v_client_workout_id,\n          'status', 'reused'\n        )\n      );\n      continue;\n    end if;\n\n    v_client_workout_id := null;\n    insert into public.client_program_workouts (\n      client_program_id,\n      client_id,\n      coach_id,\n      workout_date,\n      title,\n      coach_comment,\n      status,\n      source_program_template_id,\n      source_template_workout_id,\n      updated_at\n    )\n    values (\n      v_program_id,\n      p_client_id,\n      v_coach_id,\n      v_workout_date,\n      coalesce(nullif(trim(v_workout.title), ''), 'Тренировка'),\n      nullif(trim(coalesce(v_workout.summary, '')), ''),\n      'planned',\n      p_program_template_id,\n      v_workout.id,\n      v_now\n    )\n    on conflict (client_id, coach_id, workout_date, source_template_workout_id)\n      where source_template_workout_id is not null\n      do nothing\n    returning id into v_client_workout_id;\n\n    if v_client_workout_id is null then\n      select id\n        into v_client_workout_id\n      from public.client_program_workouts\n      where client_id = p_client_id\n        and coach_id = v_coach_id\n        and workout_date = v_workout_date\n        and source_template_workout_id = v_workout.id\n      limit 1;\n\n      if v_client_workout_id is null then\n        return jsonb_build_object('ok', false, 'error', 'db_error', 'message', 'Imported workout was not created');\n      end if;\n\n      v_reused_workouts := v_reused_workouts + 1;\n      v_imported_workouts := v_imported_workouts || jsonb_build_array(\n        jsonb_build_object(\n          'workoutDate', v_workout_date,\n          'sourceTemplateWorkoutId', v_workout.id,\n          'clientWorkoutId', v_client_workout_id,\n          'status', 'reused'\n        )\n      );\n      continue;\n    end if;\n\n    v_group_id_by_template_id := '{}'::jsonb;\n    for v_group in\n      select *\n      from public.program_template_exercise_groups\n      where program_template_workout_id = v_workout.id\n      order by sort_order, title\n    loop\n      insert into public.client_program_exercise_groups (\n        client_program_workout_id,\n        title,\n        sets,\n        rest,\n        notes,\n        sort_order,\n        source_template_group_id\n      )\n      values (\n        v_client_workout_id,\n        coalesce(nullif(trim(v_group.title), ''), 'Комбо'),\n        nullif(trim(coalesce(v_group.sets, '')), ''),\n        nullif(trim(coalesce(v_group.rest, '')), ''),\n        nullif(trim(coalesce(v_group.notes, '')), ''),\n        coalesce(v_group.sort_order, 0),\n        v_group.id\n      )\n      returning id into v_group_id;\n\n      v_group_id_by_template_id := v_group_id_by_template_id || jsonb_build_object(v_group.id::text, v_group_id::text);\n    end loop;\n\n    for v_exercise in\n      select *\n      from public.program_template_exercises\n      where program_template_workout_id = v_workout.id\n      order by sort_order, exercise_title\n    loop\n      insert into public.client_program_exercises (\n        client_program_workout_id,\n        exercise_group_id,\n        exercise_id,\n        exercise_title,\n        sets,\n        reps,\n        rest,\n        tempo,\n        notes,\n        sort_order,\n        source_template_exercise_id\n      )\n      values (\n        v_client_workout_id,\n        case\n          when v_exercise.exercise_group_id is not null\n            then (v_group_id_by_template_id->>v_exercise.exercise_group_id::text)::uuid\n          else null\n        end,\n        v_exercise.exercise_id,\n        coalesce(nullif(trim(v_exercise.exercise_title), ''), 'Упражнение'),\n        case when v_exercise.exercise_group_id is null then nullif(trim(coalesce(v_exercise.sets, '')), '') else null end,\n        nullif(trim(coalesce(v_exercise.reps, '')), ''),\n        case when v_exercise.exercise_group_id is null then nullif(trim(coalesce(v_exercise.rest, '')), '') else null end,\n        nullif(trim(coalesce(v_exercise.tempo, '')), ''),\n        nullif(trim(coalesce(v_exercise.notes, '')), ''),\n        coalesce(v_exercise.sort_order, 0),\n        v_exercise.id\n      );\n    end loop;\n\n    v_created_workouts := v_created_workouts + 1;\n    v_imported_workouts := v_imported_workouts || jsonb_build_array(\n      jsonb_build_object(\n        'workoutDate', v_workout_date,\n        'sourceTemplateWorkoutId', v_workout.id,\n        'clientWorkoutId', v_client_workout_id,\n        'status', 'created'\n      )\n    );\n  end loop;\n\n  return jsonb_build_object(\n    'ok', true,\n    'clientProgramId', v_program_id,\n    'createdWorkouts', v_created_workouts,\n    'reusedWorkouts', v_reused_workouts,\n    'importedWorkouts', v_imported_workouts\n  );\nend;\n$$;\n\ngrant execute on function public.import_program_template_workouts_to_client_calendar(text, uuid, uuid, date, uuid[], jsonb) to service_role;"}	template_workout_calendar_import_rpc	ov.shatvoryan@gmail.com	\N	\N
20260629091127	{"-- Enforce one active client_program per coach/client pair and make template\n-- workout import share the same active-program lock as runtime workout create.\n\ndo $$\nbegin\n  if exists (\n    select 1\n    from public.client_programs\n    where status = 'active'\n      and coach_id is not null\n    group by client_id, coach_id\n    having count(*) > 1\n  ) then\n    raise exception 'Cannot add active client_program uniqueness guard while duplicate active programs exist';\n  end if;\nend;\n$$;\n\ncreate unique index if not exists idx_client_programs_one_active_per_coach_client\n  on public.client_programs(client_id, coach_id)\n  where status = 'active'\n    and coach_id is not null;\n\ncreate or replace function public.import_program_template_workouts_to_client_calendar(\n  p_coach_email text,\n  p_client_id uuid,\n  p_program_template_id uuid,\n  p_start_date date default null,\n  p_template_workout_ids uuid[] default null,\n  p_workout_dates jsonb default null\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_coach_id uuid;\n  v_template record;\n  v_program_id uuid;\n  v_now timestamptz := now();\n  v_selected_count integer := 0;\n  v_matching_count integer := 0;\n  v_base_day_number integer := 1;\n  v_workout record;\n  v_workout_date date;\n  v_date_raw text;\n  v_client_workout_id uuid;\n  v_group record;\n  v_exercise record;\n  v_group_id uuid;\n  v_group_id_by_template_id jsonb;\n  v_created_workouts integer := 0;\n  v_reused_workouts integer := 0;\n  v_imported_workouts jsonb := '[]'::jsonb;\nbegin\n  if p_client_id is null then\n    return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Client id is required');\n  end if;\n\n  if p_program_template_id is null then\n    return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Program template id is required');\n  end if;\n\n  if p_start_date is null and (p_workout_dates is null or jsonb_typeof(p_workout_dates) <> 'object') then\n    return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Start date or workout date map is required');\n  end if;\n\n  if p_workout_dates is not null and jsonb_typeof(p_workout_dates) <> 'object' then\n    return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Workout dates must be an object');\n  end if;\n\n  select id\n    into v_coach_id\n  from public.coach_profiles\n  where lower(email) = lower(trim(coalesce(p_coach_email, '')))\n    and is_active = true;\n\n  if v_coach_id is null then\n    return jsonb_build_object('ok', false, 'error', 'forbidden');\n  end if;\n\n  perform 1\n  from public.coach_clients\n  where coach_id = v_coach_id\n    and client_id = p_client_id\n    and is_active = true;\n\n  if not found then\n    return jsonb_build_object('ok', false, 'error', 'forbidden');\n  end if;\n\n  select *\n    into v_template\n  from public.program_templates\n  where id = p_program_template_id\n    and is_active = true\n  for update;\n\n  if not found then\n    return jsonb_build_object('ok', false, 'error', 'not_found');\n  end if;\n\n  if v_template.coach_id is not null and v_template.coach_id <> v_coach_id then\n    return jsonb_build_object('ok', false, 'error', 'not_found');\n  end if;\n\n  perform pg_advisory_xact_lock(\n    hashtext('template-workout-import:' || v_coach_id::text || ':' || p_client_id::text || ':' || p_program_template_id::text)\n  );\n\n  perform pg_advisory_xact_lock(hashtext('active-client-program:' || v_coach_id::text || ':' || p_client_id::text));\n\n  if array_length(p_template_workout_ids, 1) is not null then\n    select count(distinct workout_id)\n      into v_selected_count\n    from unnest(p_template_workout_ids) as selected(workout_id);\n\n    select count(*)\n      into v_matching_count\n    from public.program_template_workouts\n    where program_template_id = p_program_template_id\n      and id = any(p_template_workout_ids);\n\n    if v_selected_count <> v_matching_count then\n      return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Selected workout does not belong to program template');\n    end if;\n  end if;\n\n  select coalesce(min(day_number), 1)\n    into v_base_day_number\n  from public.program_template_workouts\n  where program_template_id = p_program_template_id\n    and (\n      array_length(p_template_workout_ids, 1) is null\n      or id = any(p_template_workout_ids)\n    );\n\n  select id\n    into v_program_id\n  from public.client_programs\n  where client_id = p_client_id\n    and coach_id = v_coach_id\n    and status = 'active'\n  order by created_at desc\n  limit 1\n  for update;\n\n  if v_program_id is null then\n    insert into public.client_programs (\n      client_id,\n      coach_id,\n      title,\n      status,\n      start_date\n    )\n    values (\n      p_client_id,\n      v_coach_id,\n      coalesce(nullif(trim(v_template.title), ''), 'Индивидуальная программа'),\n      'active',\n      coalesce(p_start_date, current_date)\n    )\n    returning id into v_program_id;\n  end if;\n\n  for v_workout in\n    select *\n    from public.program_template_workouts\n    where program_template_id = p_program_template_id\n      and (\n        array_length(p_template_workout_ids, 1) is null\n        or id = any(p_template_workout_ids)\n      )\n    order by sort_order, day_number, title\n  loop\n    v_date_raw := null;\n    if p_workout_dates is not null then\n      v_date_raw := nullif(p_workout_dates->>v_workout.id::text, '');\n    end if;\n\n    begin\n      v_workout_date := coalesce(\n        v_date_raw::date,\n        p_start_date + greatest(coalesce(v_workout.day_number, v_base_day_number) - v_base_day_number, 0)\n      );\n    exception when others then\n      return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Workout date must be a valid date');\n    end;\n\n    if v_workout_date is null then\n      return jsonb_build_object('ok', false, 'error', 'invalid', 'message', 'Workout date is required');\n    end if;\n\n    select id\n      into v_client_workout_id\n    from public.client_program_workouts\n    where client_id = p_client_id\n      and coach_id = v_coach_id\n      and workout_date = v_workout_date\n      and source_template_workout_id = v_workout.id\n    limit 1\n    for update;\n\n    if v_client_workout_id is not null then\n      v_reused_workouts := v_reused_workouts + 1;\n      v_imported_workouts := v_imported_workouts || jsonb_build_array(\n        jsonb_build_object(\n          'workoutDate', v_workout_date,\n          'sourceTemplateWorkoutId', v_workout.id,\n          'clientWorkoutId', v_client_workout_id,\n          'status', 'reused'\n        )\n      );\n      continue;\n    end if;\n\n    v_client_workout_id := null;\n    insert into public.client_program_workouts (\n      client_program_id,\n      client_id,\n      coach_id,\n      workout_date,\n      title,\n      coach_comment,\n      status,\n      source_program_template_id,\n      source_template_workout_id,\n      updated_at\n    )\n    values (\n      v_program_id,\n      p_client_id,\n      v_coach_id,\n      v_workout_date,\n      coalesce(nullif(trim(v_workout.title), ''), 'Тренировка'),\n      nullif(trim(coalesce(v_workout.summary, '')), ''),\n      'planned',\n      p_program_template_id,\n      v_workout.id,\n      v_now\n    )\n    on conflict (client_id, coach_id, workout_date, source_template_workout_id)\n      where source_template_workout_id is not null\n      do nothing\n    returning id into v_client_workout_id;\n\n    if v_client_workout_id is null then\n      select id\n        into v_client_workout_id\n      from public.client_program_workouts\n      where client_id = p_client_id\n        and coach_id = v_coach_id\n        and workout_date = v_workout_date\n        and source_template_workout_id = v_workout.id\n      limit 1;\n\n      if v_client_workout_id is null then\n        return jsonb_build_object('ok', false, 'error', 'db_error', 'message', 'Imported workout was not created');\n      end if;\n\n      v_reused_workouts := v_reused_workouts + 1;\n      v_imported_workouts := v_imported_workouts || jsonb_build_array(\n        jsonb_build_object(\n          'workoutDate', v_workout_date,\n          'sourceTemplateWorkoutId', v_workout.id,\n          'clientWorkoutId', v_client_workout_id,\n          'status', 'reused'\n        )\n      );\n      continue;\n    end if;\n\n    v_group_id_by_template_id := '{}'::jsonb;\n    for v_group in\n      select *\n      from public.program_template_exercise_groups\n      where program_template_workout_id = v_workout.id\n      order by sort_order, title\n    loop\n      insert into public.client_program_exercise_groups (\n        client_program_workout_id,\n        title,\n        sets,\n        rest,\n        notes,\n        sort_order,\n        source_template_group_id\n      )\n      values (\n        v_client_workout_id,\n        coalesce(nullif(trim(v_group.title), ''), 'Комбо'),\n        nullif(trim(coalesce(v_group.sets, '')), ''),\n        nullif(trim(coalesce(v_group.rest, '')), ''),\n        nullif(trim(coalesce(v_group.notes, '')), ''),\n        coalesce(v_group.sort_order, 0),\n        v_group.id\n      )\n      returning id into v_group_id;\n\n      v_group_id_by_template_id := v_group_id_by_template_id || jsonb_build_object(v_group.id::text, v_group_id::text);\n    end loop;\n\n    for v_exercise in\n      select *\n      from public.program_template_exercises\n      where program_template_workout_id = v_workout.id\n      order by sort_order, exercise_title\n    loop\n      insert into public.client_program_exercises (\n        client_program_workout_id,\n        exercise_group_id,\n        exercise_id,\n        exercise_title,\n        sets,\n        reps,\n        rest,\n        tempo,\n        notes,\n        sort_order,\n        source_template_exercise_id\n      )\n      values (\n        v_client_workout_id,\n        case\n          when v_exercise.exercise_group_id is not null\n            then (v_group_id_by_template_id->>v_exercise.exercise_group_id::text)::uuid\n          else null\n        end,\n        v_exercise.exercise_id,\n        coalesce(nullif(trim(v_exercise.exercise_title), ''), 'Упражнение'),\n        case when v_exercise.exercise_group_id is null then nullif(trim(coalesce(v_exercise.sets, '')), '') else null end,\n        nullif(trim(coalesce(v_exercise.reps, '')), ''),\n        case when v_exercise.exercise_group_id is null then nullif(trim(coalesce(v_exercise.rest, '')), '') else null end,\n        nullif(trim(coalesce(v_exercise.tempo, '')), ''),\n        nullif(trim(coalesce(v_exercise.notes, '')), ''),\n        coalesce(v_exercise.sort_order, 0),\n        v_exercise.id\n      );\n    end loop;\n\n    v_created_workouts := v_created_workouts + 1;\n    v_imported_workouts := v_imported_workouts || jsonb_build_array(\n      jsonb_build_object(\n        'workoutDate', v_workout_date,\n        'sourceTemplateWorkoutId', v_workout.id,\n        'clientWorkoutId', v_client_workout_id,\n        'status', 'created'\n      )\n    );\n  end loop;\n\n  return jsonb_build_object(\n    'ok', true,\n    'clientProgramId', v_program_id,\n    'createdWorkouts', v_created_workouts,\n    'reusedWorkouts', v_reused_workouts,\n    'importedWorkouts', v_imported_workouts\n  );\nend;\n$$;\n\ngrant execute on function public.import_program_template_workouts_to_client_calendar(text, uuid, uuid, date, uuid[], jsonb) to service_role;"}	active_client_program_unique_guard	ov.shatvoryan@gmail.com	\N	\N
20260629093807	{"-- Coach-level privileges for managing shared/global LK resources.\n\nalter table public.coach_profiles\n  add column if not exists access_level text not null default 'coach';\n\nupdate public.coach_profiles\nset access_level = 'coach'\nwhere access_level is null\n   or access_level not in ('coach', 'head_coach');\n\ndo $$\nbegin\n  if not exists (\n    select 1\n    from pg_constraint\n    where conrelid = 'public.coach_profiles'::regclass\n      and conname = 'coach_profiles_access_level_check'\n  ) then\n    alter table public.coach_profiles\n      add constraint coach_profiles_access_level_check\n      check (access_level in ('coach', 'head_coach'));\n  end if;\nend;\n$$;"}	coach_access_level	ov.shatvoryan@gmail.com	\N	\N
20260629095121	{"-- Align program template diff-save RPC with the LK ownership/access model.\n-- The full diff-save body is preserved; this migration patches only actor lookup\n-- and template ownership checks inside the existing function definition.\n\ndo $$\ndeclare\n  v_sql text;\n  v_old_select text := $old$\n  select id\n    into v_coach_id\n  from public.coach_profiles\n  where lower(email) = lower(trim(coalesce(p_coach_email, '')))\n    and is_active = true;\n$old$;\n  v_old_select_compact text := $old$\n  select id into v_coach_id\n  from public.coach_profiles\n  where lower(email) = lower(trim(coalesce(p_coach_email, '')))\n    and is_active = true;\n$old$;\n  v_new_select text := $new$\n  select id, coalesce(access_level, 'coach')\n    into v_coach_id, v_access_level\n  from public.coach_profiles\n  where lower(email) = lower(trim(coalesce(p_coach_email, '')))\n    and is_active = true;\n$new$;\n  v_old_guard text := $old$\n  if v_template.coach_id is not null and v_template.coach_id <> v_coach_id then\n    return jsonb_build_object('ok', false, 'error', 'not_found');\n  end if;\n$old$;\n  v_new_guard text := $new$\n  if v_template.coach_id = v_coach_id then\n    null;\n  elsif coalesce(v_access_level, 'coach') = 'head_coach' then\n    null;\n  elsif v_template.coach_id is null then\n    return jsonb_build_object(\n      'ok', false,\n      'error', 'forbidden',\n      'message', 'Only head coach can edit global program templates'\n    );\n  else\n    return jsonb_build_object('ok', false, 'error', 'not_found');\n  end if;\n$new$;\nbegin\n  select pg_get_functiondef('public.save_program_template_diff(uuid,text,timestamptz,jsonb)'::regprocedure)\n    into v_sql;\n\n  if v_sql is null then\n    raise exception 'save_program_template_diff(uuid,text,timestamptz,jsonb) does not exist';\n  end if;\n\n  if position('v_access_level text;' in v_sql) = 0 then\n    v_sql := replace(v_sql, '  v_coach_id uuid;', '  v_coach_id uuid;' || chr(10) || '  v_access_level text;');\n  end if;\n\n  if position('into v_coach_id, v_access_level' in v_sql) = 0 then\n    v_sql := replace(v_sql, v_old_select, v_new_select);\n  end if;\n\n  if position('into v_coach_id, v_access_level' in v_sql) = 0 then\n    v_sql := replace(v_sql, v_old_select_compact, v_new_select);\n  end if;\n\n  if position('into v_coach_id, v_access_level' in v_sql) = 0 then\n    raise exception 'save_program_template_diff actor lookup patch failed';\n  end if;\n\n  if position('Only head coach can edit global program templates' in v_sql) = 0 then\n    v_sql := replace(v_sql, v_old_guard, v_new_guard);\n  end if;\n\n  if position('Only head coach can edit global program templates' in v_sql) = 0 then\n    raise exception 'save_program_template_diff ownership guard patch failed';\n  end if;\n\n  execute v_sql;\nend;\n$$;\n\ngrant execute on function public.save_program_template_diff(uuid, text, timestamptz, jsonb) to service_role;"}	program_template_diff_access_level_guard	ov.shatvoryan@gmail.com	\N	\N
20260702114146	{"-- Make coach act/application totals use a single source of truth.\n-- Every row displayed in coach act/application PDFs is treated as payable.\n-- Master-class rows are payable when displayed; for kapitanstar_coach the\n-- existing close logic normalizes 110 RUB extra-coach rows into two displayed\n-- people at the 55 RUB base displayed master-class rate.\n\ncreate or replace function public.calculate_coach_act_totals(p_act_id uuid)\nreturns table (\n  total_hours numeric,\n  total_people numeric,\n  total_sum numeric\n)\nlanguage plpgsql\nas $function$\ndeclare\n  a public.coach_acts%rowtype;\n\n  v_group_rate numeric := 265;\n  v_personal_rate numeric;\n  v_video_no_voice_rate numeric;\n  v_video_voice_rate numeric;\n  v_smm_rate numeric;\n  v_master_rate numeric;\nbegin\n  select * into a from public.coach_acts where id = p_act_id;\n  if not found then\n    raise exception 'coach_act_not_found: %', p_act_id;\n  end if;\n\n  select cpr.amount into v_group_rate\n  from public.coach_payout_rules cpr\n  join public.training_formats tf on tf.id = cpr.training_format_id\n  where cpr.is_active = true\n    and cpr.coach_role = 'main'\n    and cpr.rate_type = 'per_person'\n    and tf.slug in ('group', 'ds')\n    and (cpr.main_coach_handle = a.coach_handle or cpr.main_coach_handle is null)\n  order by (cpr.main_coach_handle = a.coach_handle) desc, tf.slug = 'group' desc\n  limit 1;\n  v_group_rate := coalesce(v_group_rate, 265);\n\n  select ranked.amount into v_video_no_voice_rate\n  from (\n    select amount, count(*) as rows\n    from public.content_earnings\n    where coach_handle = a.coach_handle and earning_type = 'video_no_voice'\n    group by amount\n  ) ranked\n  order by ranked.rows desc, ranked.amount desc\n  limit 1;\n\n  select ranked.amount into v_video_voice_rate\n  from (\n    select amount, count(*) as rows\n    from public.content_earnings\n    where coach_handle = a.coach_handle and earning_type = 'video_voice_extra'\n    group by amount\n  ) ranked\n  order by ranked.rows desc, ranked.amount desc\n  limit 1;\n\n  select ranked.amount into v_smm_rate\n  from (\n    select amount, count(*) as rows\n    from public.content_earnings\n    where coach_handle = a.coach_handle and earning_type in ('smm_base', 'smm_info_extra')\n    group by amount\n  ) ranked\n  order by ranked.rows desc, ranked.amount desc\n  limit 1;\n\n  select min(cpr.amount) into v_master_rate\n  from public.coach_payout_rules cpr\n  join public.training_formats tf on tf.id = cpr.training_format_id\n  where cpr.is_active = true\n    and cpr.coach_role = 'extra'\n    and cpr.rate_type = 'per_person'\n    and cpr.extra_coach_handle = a.coach_handle\n    and tf.slug = 'group';\n\n  -- These content/document rates are not represented by a dedicated rate table.\n  -- Keep fallback constants centralized here so create/close/PDF/n8n do not\n  -- duplicate business logic.\n  v_video_no_voice_rate := coalesce(v_video_no_voice_rate, 640);\n  v_video_voice_rate := coalesce(v_video_voice_rate, 425);\n  v_smm_rate := coalesce(v_smm_rate, 530);\n  v_master_rate := coalesce(v_master_rate, 55);\n\n  -- Prefer a historical document rate when it can be inferred from prior\n  -- non-zero acts for the same coach. This preserves the PDF-facing rate where\n  -- payout rules are absent or do not match already generated documents.\n  select avg((\n      ca.total_sum\n      - coalesce(ca.group_people, 0) * v_group_rate\n      - coalesce(ca.video_hours, 0) * v_video_no_voice_rate\n      - coalesce(ca.video_hours_voice, 0) * v_video_voice_rate\n      - coalesce(ca.smm_hours, 0) * v_smm_rate\n      - coalesce(ca.master_people, 0) * v_master_rate\n    ) / nullif(ca.personal_people, 0))\n  into v_personal_rate\n  from public.coach_acts ca\n  where ca.coach_handle = a.coach_handle\n    and coalesce(ca.personal_people, 0) > 0\n    and coalesce(ca.total_sum, 0) > 0;\n\n  if v_personal_rate is null then\n    select ce.amount / nullif(ce.people_count, 0) into v_personal_rate\n    from public.coach_earnings ce\n    join public.training_formats tf on tf.id = ce.training_format_id\n    join public.coach_profiles cp on cp.id = ce.coach_id\n    where cp.coach_name = a.coach_handle\n      and ce.status = 'main'\n      and tf.slug = 'personal'\n      and coalesce(ce.people_count, 0) <> 0\n    order by ce.earned_at desc\n    limit 1;\n  end if;\n\n  if v_personal_rate is null then\n    select cpr.amount into v_personal_rate\n    from public.coach_payout_rules cpr\n    join public.training_formats tf on tf.id = cpr.training_format_id\n    where cpr.is_active = true\n      and cpr.coach_role = 'main'\n      and cpr.rate_type = 'fixed'\n      and tf.slug = 'personal'\n      and (cpr.main_coach_handle = a.coach_handle or cpr.main_coach_handle is null)\n    order by (cpr.main_coach_handle = a.coach_handle) desc\n    limit 1;\n  end if;\n\n  v_personal_rate := coalesce(v_personal_rate, 1600);\n\n  total_hours := coalesce(a.personal_hours, 0) + coalesce(a.group_hours, 0) + coalesce(a.video_hours, 0) + coalesce(a.video_hours_voice, 0) + coalesce(a.smm_hours, 0);\n  total_people := coalesce(a.personal_people, 0) + coalesce(a.group_people, 0) + coalesce(a.master_people, 0);\n  total_sum := round(\n    coalesce(a.personal_people, 0) * v_personal_rate\n    + coalesce(a.group_people, 0) * v_group_rate\n    + coalesce(a.video_hours, 0) * v_video_no_voice_rate\n    + coalesce(a.video_hours_voice, 0) * v_video_voice_rate\n    + coalesce(a.smm_hours, 0) * v_smm_rate\n    + coalesce(a.master_people, 0) * v_master_rate,\n    0\n  );\n\n  return next;\nend;\n$function$;\n\ncreate or replace function public.create_next_coach_act(p_previous_act_id uuid)\nreturns jsonb\nlanguage plpgsql\nas $function$\ndeclare\n  prev public.coach_acts%rowtype;\n  s public.coach_act_settings%rowtype;\n  v_duration integer;\n  v_new_start date;\n  v_new_end date;\n  v_day_signed date;\n  v_act_number text;\n  v_group_hours integer;\n  v_group_people integer;\n  v_personal integer := 0;\n  v_video integer := 0;\n  v_video_voice integer := 0;\n  v_smm integer := 0;\n  v_master integer := 0;\n  v_new_id uuid;\n  v_totals record;\nbegin\n  select * into prev from public.coach_acts where id = p_previous_act_id;\n  if not found then\n    return jsonb_build_object('ok', false, 'error', 'previous_act_not_found');\n  end if;\n\n  select * into s\n  from public.coach_act_settings\n  where coach_handle = prev.coach_handle and is_active = true;\n  if not found then\n    return jsonb_build_object('ok', false, 'error', 'coach_act_settings_not_found', 'coach_handle', prev.coach_handle);\n  end if;\n\n  v_duration := public.random_int_between(18, 23);\n  v_new_start := prev.period_end + interval '1 day';\n  v_new_end := v_new_start + (v_duration || ' days')::interval;\n  v_day_signed := v_new_end + interval '1 day';\n  v_act_number := public.next_act_number(prev.act_number);\n\n  v_group_hours := public.count_act_group_days(v_new_start, v_new_end, s.group_days);\n  v_group_people := v_group_hours * coalesce(s.group_people_multiplier, 0);\n\n  if s.has_personal then v_personal := public.random_int_between(s.personal_min, s.personal_max); end if;\n  if s.has_video then v_video := public.random_int_between(s.video_min, s.video_max); end if;\n  if s.has_video_voice then v_video_voice := public.random_int_between(s.video_voice_min, s.video_voice_max); end if;\n  if s.has_smm then v_smm := public.random_int_between(s.smm_min, s.smm_max); end if;\n  if s.has_master then v_master := public.random_int_between(s.master_people_min, s.master_people_max); end if;\n\n  insert into public.coach_acts (\n    act_number, coach_handle, period_start, period_end, day_signed, status,\n    personal_hours, personal_people, group_hours, group_people,\n    video_hours, video_hours_voice, smm_hours, master_people\n  ) values (\n    v_act_number, prev.coach_handle, v_new_start, v_new_end, v_day_signed, 'work',\n    v_personal, v_personal, v_group_hours, v_group_people,\n    v_video, v_video_voice, v_smm, v_master\n  ) returning id into v_new_id;\n\n  select * into v_totals from public.calculate_coach_act_totals(v_new_id);\n\n  update public.coach_acts\n  set total_hours = v_totals.total_hours,\n      total_people = v_totals.total_people,\n      total_sum = v_totals.total_sum,\n      updated_at = now()\n  where id = v_new_id;\n\n  return jsonb_build_object(\n    'ok', true,\n    'new_act_id', v_new_id,\n    'act_number', v_act_number,\n    'coach_handle', prev.coach_handle,\n    'period_start', v_new_start,\n    'period_end', v_new_end,\n    'day_signed', v_day_signed,\n    'total_hours', v_totals.total_hours,\n    'total_people', v_totals.total_people,\n    'total_sum', v_totals.total_sum\n  );\nend;\n$function$;\n\ncreate or replace function public.close_coach_act(p_act_id uuid)\nreturns jsonb\nlanguage plpgsql\nas $function$\ndeclare\n  a public.coach_acts%rowtype;\n  v_personal_hours numeric := 0;\n  v_personal_people numeric := 0;\n  v_group_hours numeric := 0;\n  v_group_people numeric := 0;\n  v_video_hours numeric := 0;\n  v_video_hours_voice numeric := 0;\n  v_smm_hours numeric := 0;\n  v_master_people numeric := 0;\n  v_totals record;\nbegin\n  select * into a from public.coach_acts where id = p_act_id for update;\n  if not found then\n    return jsonb_build_object('ok', false, 'error', 'act_not_found');\n  end if;\n\n  select count(*), coalesce(sum(ce.people_count), 0)\n  into v_personal_hours, v_personal_people\n  from public.coach_earnings ce\n  join public.training_formats tf on tf.id = ce.training_format_id\n  where ce.status = 'main'\n    and ce.earned_at::date between a.period_start and a.period_end\n    and tf.slug = 'personal'\n    and exists (select 1 from public.coach_profiles cp where cp.id = ce.coach_id and cp.coach_name = a.coach_handle);\n\n  select coalesce(sum(case when tf.slug = 'group' then 1 else 0 end), 0), coalesce(sum(ce.people_count), 0)\n  into v_group_hours, v_group_people\n  from public.coach_earnings ce\n  join public.training_formats tf on tf.id = ce.training_format_id\n  where ce.status = 'main'\n    and ce.earned_at::date between a.period_start and a.period_end\n    and tf.slug in ('group', 'ds')\n    and exists (select 1 from public.coach_profiles cp where cp.id = ce.coach_id and cp.coach_name = a.coach_handle);\n\n  select coalesce(sum(case when earning_type = 'video_no_voice' then 1 else 0 end), 0),\n         coalesce(sum(case when earning_type = 'video_voice_extra' then 1 else 0 end), 0),\n         coalesce(sum(case when earning_type in ('smm_base', 'smm_info_extra') then 1 else 0 end), 0)\n  into v_video_hours, v_video_hours_voice, v_smm_hours\n  from public.content_earnings\n  where coach_handle = a.coach_handle\n    and earning_date between a.period_start and a.period_end;\n\n  if a.coach_handle = 'kapitanstar_coach' then\n    select coalesce(sum(case when p.coach_handle_snapshot = 'dima_dubinin' then coalesce(ce.people_count, 1) * 2 else coalesce(ce.people_count, 1) end), 0)\n    into v_master_people\n    from public.coach_earnings ce\n    left join public.pnl_entries p on p.scheduled_workout_id = ce.scheduled_workout_id\n    where ce.status = 'extra'\n      and ce.earned_at::date between a.period_start and a.period_end\n      and exists (select 1 from public.coach_profiles cp where cp.id = ce.coach_id and cp.coach_name = 'kapitanstar_coach');\n  end if;\n\n  update public.coach_acts\n  set personal_hours = v_personal_hours,\n      personal_people = v_personal_people,\n      group_hours = v_group_hours,\n      group_people = v_group_people,\n      video_hours = v_video_hours,\n      video_hours_voice = v_video_hours_voice,\n      smm_hours = v_smm_hours,\n      master_people = v_master_people,\n      updated_at = now()\n  where id = a.id;\n\n  select * into v_totals from public.calculate_coach_act_totals(a.id);\n\n  update public.coach_acts\n  set total_hours = v_totals.total_hours,\n      total_people = v_totals.total_people,\n      total_sum = v_totals.total_sum,\n      status = 'doc_act_created',\n      updated_at = now()\n  where id = a.id;\n\n  return jsonb_build_object(\n    'ok', true,\n    'act_id', a.id,\n    'act_number', a.act_number,\n    'coach_handle', a.coach_handle,\n    'personal_hours', v_personal_hours,\n    'personal_people', v_personal_people,\n    'group_hours', v_group_hours,\n    'group_people', v_group_people,\n    'video_hours', v_video_hours,\n    'video_hours_voice', v_video_hours_voice,\n    'smm_hours', v_smm_hours,\n    'master_people', v_master_people,\n    'total_hours', v_totals.total_hours,\n    'total_people', v_totals.total_people,\n    'total_sum', v_totals.total_sum\n  );\nend;\n$function$;\n\nwith mismatches as (\n  select ca.id, calc.total_hours, calc.total_people, calc.total_sum\n  from public.coach_acts ca\n  cross join lateral public.calculate_coach_act_totals(ca.id) calc\n  where ca.total_hours is distinct from calc.total_hours\n     or ca.total_people is distinct from calc.total_people\n     or ca.total_sum is distinct from calc.total_sum\n)\nupdate public.coach_acts ca\nset total_hours = mismatches.total_hours,\n    total_people = mismatches.total_people,\n    total_sum = mismatches.total_sum,\n    updated_at = now()\nfrom mismatches\nwhere ca.id = mismatches.id;"}	coach_act_totals_helper	ov.shatvoryan@gmail.com	\N	\N
20260702114304	{"-- Keep calculate_coach_act_totals idempotent after backfills.\n-- Do not infer rates from mutable coach_acts.total_sum; read rates from\n-- earnings/rules, with document fallback constants centralized in this helper.\n\ncreate or replace function public.calculate_coach_act_totals(p_act_id uuid)\nreturns table (\n  total_hours numeric,\n  total_people numeric,\n  total_sum numeric\n)\nlanguage plpgsql\nas $function$\ndeclare\n  a public.coach_acts%rowtype;\n  v_group_rate numeric := 265;\n  v_personal_rate numeric;\n  v_video_no_voice_rate numeric;\n  v_video_voice_rate numeric;\n  v_smm_rate numeric;\n  v_master_rate numeric;\nbegin\n  select * into a from public.coach_acts where id = p_act_id;\n  if not found then\n    raise exception 'coach_act_not_found: %', p_act_id;\n  end if;\n\n  select cpr.amount into v_group_rate\n  from public.coach_payout_rules cpr\n  join public.training_formats tf on tf.id = cpr.training_format_id\n  where cpr.is_active = true\n    and cpr.coach_role = 'main'\n    and cpr.rate_type = 'per_person'\n    and tf.slug in ('group', 'ds')\n    and (cpr.main_coach_handle = a.coach_handle or cpr.main_coach_handle is null)\n  order by (cpr.main_coach_handle = a.coach_handle) desc, tf.slug = 'group' desc\n  limit 1;\n\n  select ranked.amount into v_video_no_voice_rate\n  from (\n    select amount, count(*) as rows\n    from public.content_earnings\n    where coach_handle = a.coach_handle and earning_type = 'video_no_voice'\n    group by amount\n  ) ranked\n  order by ranked.rows desc, ranked.amount desc\n  limit 1;\n\n  select ranked.amount into v_video_voice_rate\n  from (\n    select amount, count(*) as rows\n    from public.content_earnings\n    where coach_handle = a.coach_handle and earning_type = 'video_voice_extra'\n    group by amount\n  ) ranked\n  order by ranked.rows desc, ranked.amount desc\n  limit 1;\n\n  select ranked.amount into v_smm_rate\n  from (\n    select amount, count(*) as rows\n    from public.content_earnings\n    where coach_handle = a.coach_handle and earning_type in ('smm_base', 'smm_info_extra')\n    group by amount\n  ) ranked\n  order by ranked.rows desc, ranked.amount desc\n  limit 1;\n\n  select min(cpr.amount) into v_master_rate\n  from public.coach_payout_rules cpr\n  join public.training_formats tf on tf.id = cpr.training_format_id\n  where cpr.is_active = true\n    and cpr.coach_role = 'extra'\n    and cpr.rate_type = 'per_person'\n    and cpr.extra_coach_handle = a.coach_handle\n    and tf.slug = 'group';\n\n  select ce.amount / nullif(ce.people_count, 0) into v_personal_rate\n  from public.coach_earnings ce\n  join public.training_formats tf on tf.id = ce.training_format_id\n  join public.coach_profiles cp on cp.id = ce.coach_id\n  where cp.coach_name = a.coach_handle\n    and ce.status = 'main'\n    and tf.slug = 'personal'\n    and coalesce(ce.people_count, 0) <> 0\n  order by ce.earned_at desc\n  limit 1;\n\n  -- Document-rate fallbacks live here only. The kapitanstar_coach personal\n  -- rate is 2130 in existing PDF rows/historical acts; coach_payout_rules has\n  -- no matching 2130 row at the time of this migration.\n  if v_personal_rate is null and a.coach_handle = 'kapitanstar_coach' then\n    v_personal_rate := 2130;\n  end if;\n\n  if v_personal_rate is null then\n    select cpr.amount into v_personal_rate\n    from public.coach_payout_rules cpr\n    join public.training_formats tf on tf.id = cpr.training_format_id\n    where cpr.is_active = true\n      and cpr.coach_role = 'main'\n      and cpr.rate_type = 'fixed'\n      and tf.slug = 'personal'\n      and (cpr.main_coach_handle = a.coach_handle or cpr.main_coach_handle is null)\n    order by (cpr.main_coach_handle = a.coach_handle) desc\n    limit 1;\n  end if;\n\n  v_group_rate := coalesce(v_group_rate, 265);\n  v_video_no_voice_rate := coalesce(v_video_no_voice_rate, 640);\n  v_video_voice_rate := coalesce(v_video_voice_rate, 425);\n  v_smm_rate := coalesce(v_smm_rate, 530);\n  v_master_rate := coalesce(v_master_rate, 55);\n  v_personal_rate := coalesce(v_personal_rate, 1600);\n\n  total_hours := coalesce(a.personal_hours, 0) + coalesce(a.group_hours, 0) + coalesce(a.video_hours, 0) + coalesce(a.video_hours_voice, 0) + coalesce(a.smm_hours, 0);\n  total_people := coalesce(a.personal_people, 0) + coalesce(a.group_people, 0) + coalesce(a.master_people, 0);\n  total_sum := round(\n    coalesce(a.personal_people, 0) * v_personal_rate\n    + coalesce(a.group_people, 0) * v_group_rate\n    + coalesce(a.video_hours, 0) * v_video_no_voice_rate\n    + coalesce(a.video_hours_voice, 0) * v_video_voice_rate\n    + coalesce(a.smm_hours, 0) * v_smm_rate\n    + coalesce(a.master_people, 0) * v_master_rate,\n    0\n  );\n\n  return next;\nend;\n$function$;\n\nwith mismatches as (\n  select ca.id, calc.total_hours, calc.total_people, calc.total_sum\n  from public.coach_acts ca\n  cross join lateral public.calculate_coach_act_totals(ca.id) calc\n  where ca.total_hours is distinct from calc.total_hours\n     or ca.total_people is distinct from calc.total_people\n     or ca.total_sum is distinct from calc.total_sum\n)\nupdate public.coach_acts ca\nset total_hours = mismatches.total_hours,\n    total_people = mismatches.total_people,\n    total_sum = mismatches.total_sum,\n    updated_at = now()\nfrom mismatches\nwhere ca.id = mismatches.id;"}	coach_act_totals_stable_rates	ov.shatvoryan@gmail.com	\N	\N
20260702170741	{"-- Align selected template-workout calendar import with the LK access model.\n-- This patches only actor lookup + template visibility inside the existing RPC.\n-- Student ownership validation, idempotency, copy logic, and active client_program\n-- lookup/creation are intentionally left unchanged.\n\ndo $$\ndeclare\n  v_sql text;\n  v_old_select text := $old$\n  select id\n    into v_coach_id\n  from public.coach_profiles\n  where lower(email) = lower(trim(coalesce(p_coach_email, '')))\n    and is_active = true;\n$old$;\n  v_new_select text := $new$\n  select id, coalesce(access_level, 'coach')\n    into v_coach_id, v_access_level\n  from public.coach_profiles\n  where lower(email) = lower(trim(coalesce(p_coach_email, '')))\n    and is_active = true;\n$new$;\n  v_old_guard text := $old$\n  if v_template.coach_id is not null and v_template.coach_id <> v_coach_id then\n    return jsonb_build_object('ok', false, 'error', 'not_found');\n  end if;\n$old$;\n  v_new_guard text := $new$\n  if v_template.coach_id is null then\n    null;\n  elsif v_template.coach_id = v_coach_id then\n    null;\n  elsif coalesce(v_access_level, 'coach') = 'head_coach' then\n    null;\n  else\n    return jsonb_build_object('ok', false, 'error', 'not_found');\n  end if;\n$new$;\nbegin\n  select pg_get_functiondef('public.import_program_template_workouts_to_client_calendar(text,uuid,uuid,date,uuid[],jsonb)'::regprocedure)\n    into v_sql;\n\n  if v_sql is null then\n    raise exception 'import_program_template_workouts_to_client_calendar(text,uuid,uuid,date,uuid[],jsonb) does not exist';\n  end if;\n\n  if position('v_access_level text;' in v_sql) = 0 then\n    v_sql := replace(v_sql, '  v_coach_id uuid;', '  v_coach_id uuid;' || chr(10) || '  v_access_level text;');\n  end if;\n\n  if position('into v_coach_id, v_access_level' in v_sql) = 0 then\n    v_sql := replace(v_sql, v_old_select, v_new_select);\n  end if;\n\n  if position('into v_coach_id, v_access_level' in v_sql) = 0 then\n    raise exception 'import_program_template_workouts actor lookup patch failed';\n  end if;\n\n  if position('coalesce(v_access_level, ''coach'') = ''head_coach''' in v_sql) = 0 then\n    v_sql := replace(v_sql, v_old_guard, v_new_guard);\n  end if;\n\n  if position('coalesce(v_access_level, ''coach'') = ''head_coach''' in v_sql) = 0 then\n    raise exception 'import_program_template_workouts template visibility patch failed';\n  end if;\n\n  execute v_sql;\nend;\n$$;\n\ngrant execute on function public.import_program_template_workouts_to_client_calendar(text, uuid, uuid, date, uuid[], jsonb) to service_role;"}	import_template_workouts_access_level	ov.shatvoryan@gmail.com	\N	\N
20260708114401	{"-- Add Georgiy's real coach profile details and support the requested\n-- Instagram content hashtag. P&L remains sourced from content_earnings via\n-- monthly_pnl_view; this migration intentionally does not touch pnl_entries.\n\nupdate public.coach_profiles\nset\n  email = 'carpediem21@yandex.ru',\n  display_name = 'Георгий Шахназаров',\n  updated_at = now()\nwhere lower(coach_name) = lower('Gshakhnazarov');\n\ndo $$\ndeclare\n  v_sql text;\n  v_old_condition text := 'if v_text like ''%#shakhnazarov%'' then';\n  v_new_condition text := 'if v_text like ''%#gshakhnazarov%'' or v_text like ''%#shakhnazarov%'' then';\nbegin\n  select pg_get_functiondef('public.process_instagram_post(uuid)'::regprocedure)\n    into v_sql;\n\n  if v_sql is null then\n    raise exception 'process_instagram_post(uuid) does not exist';\n  end if;\n\n  if position('%#gshakhnazarov%' in v_sql) = 0 then\n    v_sql := replace(v_sql, v_old_condition, v_new_condition);\n  end if;\n\n  if position('%#gshakhnazarov%' in v_sql) = 0 then\n    raise exception 'process_instagram_post Georgiy hashtag patch failed';\n  end if;\n\n  execute v_sql;\nend;\n$$;"}	georgiy_content_hashtag	ov.shatvoryan@gmail.com	\N	\N
20260711153106	{"create or replace function public.sync_client_coach_link_on_clients_coach_change()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_result jsonb;\nbegin\n  if tg_op = 'INSERT' or old.coach is distinct from new.coach then\n    v_result := public.sync_client_coach_link(new.id);\n\n    if coalesce(v_result->>'ok', 'false') <> 'true' then\n      raise notice 'sync_client_coach_link skipped for client %, result: %', new.id, v_result;\n    end if;\n  end if;\n\n  return new;\nend;\n$function$;\n\ndrop trigger if exists clients_coach_sync_trigger on public.clients;\n\ncreate trigger clients_coach_sync_trigger\nafter insert or update of coach on public.clients\nfor each row\nexecute function public.sync_client_coach_link_on_clients_coach_change();"}	clients_coach_sync_trigger	ov.shatvoryan@gmail.com	\N	\N
20260708201203	{"create or replace function public.close_coach_act(p_act_id uuid)\nreturns jsonb\nlanguage plpgsql\nas $function$\ndeclare\n  a public.coach_acts%rowtype;\n  v_personal_hours numeric := 0;\n  v_personal_people numeric := 0;\n  v_group_hours numeric := 0;\n  v_group_people numeric := 0;\n  v_video_hours numeric := 0;\n  v_video_hours_voice numeric := 0;\n  v_smm_hours numeric := 0;\n  v_master_people numeric := 0;\n  v_totals record;\nbegin\n  select *\n  into a\n  from public.coach_acts\n  where id = p_act_id\n  for update;\n\n  if not found then\n    return jsonb_build_object('ok', false, 'error', 'act_not_found');\n  end if;\n\n  select\n    count(*),\n    coalesce(sum(ce.people_count), 0)\n  into\n    v_personal_hours,\n    v_personal_people\n  from public.coach_earnings ce\n  join public.training_formats tf on tf.id = ce.training_format_id\n  where ce.status = 'main'\n    and ce.earned_at::date between a.period_start and a.period_end\n    and tf.slug = 'personal'\n    and exists (\n      select 1\n      from public.coach_profiles cp\n      where cp.id = ce.coach_id\n        and cp.coach_name = a.coach_handle\n    );\n\n  select\n    coalesce(\n      count(distinct (\n        coalesce(sw.scheduled_at::date, ce.earned_at::date),\n        coalesce(nullif(sw.title, ''), ce.scheduled_workout_id::text, ce.id::text)\n      )) filter (where tf.slug = 'group'),\n      0\n    ),\n    coalesce(sum(ce.people_count), 0)\n  into\n    v_group_hours,\n    v_group_people\n  from public.coach_earnings ce\n  join public.training_formats tf on tf.id = ce.training_format_id\n  left join public.scheduled_workouts sw on sw.id = ce.scheduled_workout_id\n  where ce.status = 'main'\n    and ce.earned_at::date between a.period_start and a.period_end\n    and tf.slug in ('group', 'ds')\n    and exists (\n      select 1\n      from public.coach_profiles cp\n      where cp.id = ce.coach_id\n        and cp.coach_name = a.coach_handle\n    );\n\n  select\n    coalesce(sum(case when earning_type = 'video_no_voice' then 1 else 0 end), 0),\n    coalesce(sum(case when earning_type = 'video_voice_extra' then 1 else 0 end), 0),\n    coalesce(sum(case when earning_type in ('smm_base', 'smm_info_extra') then 1 else 0 end), 0)\n  into\n    v_video_hours,\n    v_video_hours_voice,\n    v_smm_hours\n  from public.content_earnings\n  where coach_handle = a.coach_handle\n    and earning_date between a.period_start and a.period_end;\n\n  if a.coach_handle = 'kapitanstar_coach' then\n    select coalesce(\n      sum(\n        case\n          when p.coach_handle_snapshot = 'dima_dubinin'\n            then coalesce(ce.people_count, 1) * 2\n          else coalesce(ce.people_count, 1)\n        end\n      ),\n      0\n    )\n    into v_master_people\n    from public.coach_earnings ce\n    left join public.pnl_entries p on p.scheduled_workout_id = ce.scheduled_workout_id\n    where ce.status = 'extra'\n      and ce.earned_at::date between a.period_start and a.period_end\n      and exists (\n        select 1\n        from public.coach_profiles cp\n        where cp.id = ce.coach_id\n          and cp.coach_name = 'kapitanstar_coach'\n      );\n  end if;\n\n  update public.coach_acts\n  set\n    personal_hours = v_personal_hours,\n    personal_people = v_personal_people,\n    group_hours = v_group_hours,\n    group_people = v_group_people,\n    video_hours = v_video_hours,\n    video_hours_voice = v_video_hours_voice,\n    smm_hours = v_smm_hours,\n    master_people = v_master_people,\n    updated_at = now()\n  where id = a.id;\n\n  select *\n  into v_totals\n  from public.calculate_coach_act_totals(a.id);\n\n  update public.coach_acts\n  set\n    total_hours = v_totals.total_hours,\n    total_people = v_totals.total_people,\n    total_sum = v_totals.total_sum,\n    status = 'doc_act_created',\n    updated_at = now()\n  where id = a.id;\n\n  return jsonb_build_object(\n    'ok', true,\n    'act_id', a.id,\n    'act_number', a.act_number,\n    'coach_handle', a.coach_handle,\n    'personal_hours', v_personal_hours,\n    'personal_people', v_personal_people,\n    'group_hours', v_group_hours,\n    'group_people', v_group_people,\n    'video_hours', v_video_hours,\n    'video_hours_voice', v_video_hours_voice,\n    'smm_hours', v_smm_hours,\n    'master_people', v_master_people,\n    'total_hours', v_totals.total_hours,\n    'total_people', v_totals.total_people,\n    'total_sum', v_totals.total_sum\n  );\nend;\n$function$;\n\ndo $$\ndeclare\n  a public.coach_acts%rowtype;\n  v_group_hours numeric := 0;\n  v_group_people numeric := 0;\n  v_totals record;\nbegin\n  select *\n  into a\n  from public.coach_acts\n  where act_number = 'SPB-FI-12';\n\n  if not found then\n    raise notice 'coach_act SPB-FI-12 not found, skipping targeted backfill';\n    return;\n  end if;\n\n  select\n    coalesce(\n      count(distinct (\n        coalesce(sw.scheduled_at::date, ce.earned_at::date),\n        coalesce(nullif(sw.title, ''), ce.scheduled_workout_id::text, ce.id::text)\n      )) filter (where tf.slug = 'group'),\n      0\n    ),\n    coalesce(sum(ce.people_count), 0)\n  into\n    v_group_hours,\n    v_group_people\n  from public.coach_earnings ce\n  join public.training_formats tf on tf.id = ce.training_format_id\n  left join public.scheduled_workouts sw on sw.id = ce.scheduled_workout_id\n  where ce.status = 'main'\n    and ce.earned_at::date between a.period_start and a.period_end\n    and tf.slug in ('group', 'ds')\n    and exists (\n      select 1\n      from public.coach_profiles cp\n      where cp.id = ce.coach_id\n        and cp.coach_name = a.coach_handle\n    );\n\n  update public.coach_acts\n  set\n    group_hours = v_group_hours,\n    group_people = v_group_people,\n    updated_at = now()\n  where id = a.id;\n\n  select *\n  into v_totals\n  from public.calculate_coach_act_totals(a.id);\n\n  update public.coach_acts\n  set\n    total_hours = v_totals.total_hours,\n    total_people = v_totals.total_people,\n    total_sum = v_totals.total_sum,\n    updated_at = now()\n  where id = a.id;\nend $$;"}	fix_coach_act_group_hours	ov.shatvoryan@gmail.com	\N	\N
20260709115503	{"create or replace view public.monthly_pnl_view as\nwith months as (\n  select distinct date_trunc('month'::text, pnl_entries.pnl_date)::date as month\n  from public.pnl_entries\n  where pnl_entries.reversed_at is null\n\n  union\n\n  select distinct date_trunc('month'::text, business_expenses.expense_month::timestamp with time zone)::date as month\n  from public.business_expenses\n\n  union\n\n  select distinct date_trunc('month'::text, purchases.created_time)::date as month\n  from public.purchases\n  where lower(coalesce(purchases.status, ''::text)) = any (array['paid'::text, 'matched'::text])\n\n  union\n\n  select distinct date_trunc('month'::text, content_earnings.earning_date::timestamp with time zone)::date as month\n  from public.content_earnings\n),\npnl as (\n  select\n    date_trunc('month'::text, pnl_entries.pnl_date)::date as month,\n    sum(coalesce(pnl_entries.revenue_amount, 0::numeric)) as total_revenue,\n    sum(\n      case\n        when coalesce(pnl_entries.entry_type, 'workout'::text) = 'workout'::text then coalesce(pnl_entries.revenue_amount, 0::numeric)\n        else 0::numeric\n      end\n    ) as workout_revenue,\n    sum(\n      case\n        when pnl_entries.entry_type = 'write_off'::text then coalesce(pnl_entries.revenue_amount, 0::numeric)\n        else 0::numeric\n      end\n    ) as write_off_revenue,\n    sum(coalesce(pnl_entries.main_coach_expense_amount, 0::numeric)) as main_coach_expenses,\n    sum(coalesce(pnl_entries.extra_coach_expense_amount, 0::numeric)) as extra_coach_expenses,\n    sum(coalesce(pnl_entries.studio_expense_amount, 0::numeric)) as studio_expenses\n  from public.pnl_entries\n  where pnl_entries.reversed_at is null\n  group by (date_trunc('month'::text, pnl_entries.pnl_date)::date)\n),\nexpenses as (\n  select\n    date_trunc('month'::text, business_expenses.expense_month::timestamp with time zone)::date as month,\n    sum(coalesce(business_expenses.amount_rub, 0::numeric)) as business_expenses\n  from public.business_expenses\n  group by (date_trunc('month'::text, business_expenses.expense_month::timestamp with time zone)::date)\n),\ncontent as (\n  select\n    date_trunc('month'::text, content_earnings.earning_date::timestamp with time zone)::date as month,\n    sum(coalesce(content_earnings.amount, 0::numeric)) as content_expenses\n  from public.content_earnings\n  group by (date_trunc('month'::text, content_earnings.earning_date::timestamp with time zone)::date)\n),\nacquiring as (\n  select\n    date_trunc('month'::text, pnl_entries.pnl_date)::date as month,\n    sum(\n      round(\n        coalesce(pnl_entries.revenue_amount, 0::numeric) *\n        case\n          when upper(coalesce(pnl_entries.client_currency, 'RUB'::text)) = 'RUB'::text then 0.031\n          else 0.025\n        end,\n        2\n      )\n    ) as acquiring_fees\n  from public.pnl_entries\n  where pnl_entries.reversed_at is null\n  group by (date_trunc('month'::text, pnl_entries.pnl_date)::date)\n)\nselect\n  m.month,\n  coalesce(p.total_revenue, 0::numeric) as total_revenue,\n  coalesce(p.workout_revenue, 0::numeric) as workout_revenue,\n  coalesce(p.write_off_revenue, 0::numeric) as write_off_revenue,\n  coalesce(a.acquiring_fees, 0::numeric) as acquiring_fees,\n  coalesce(p.main_coach_expenses, 0::numeric) as main_coach_expenses,\n  coalesce(p.extra_coach_expenses, 0::numeric) as extra_coach_expenses,\n  coalesce(p.main_coach_expenses, 0::numeric) + coalesce(p.extra_coach_expenses, 0::numeric) as total_coach_expenses,\n  coalesce(p.studio_expenses, 0::numeric) as studio_expenses,\n  coalesce(e.business_expenses, 0::numeric) as business_expenses,\n  coalesce(p.total_revenue, 0::numeric)\n    - coalesce(a.acquiring_fees, 0::numeric)\n    - coalesce(p.main_coach_expenses, 0::numeric)\n    - coalesce(p.extra_coach_expenses, 0::numeric)\n    - coalesce(p.studio_expenses, 0::numeric)\n    - coalesce(e.business_expenses, 0::numeric)\n    - coalesce(c.content_expenses, 0::numeric) as net_profit,\n  coalesce(p.total_revenue, 0::numeric) - coalesce(a.acquiring_fees, 0::numeric) as revenue_after_acquiring,\n  coalesce(p.main_coach_expenses, 0::numeric)\n    + coalesce(p.extra_coach_expenses, 0::numeric)\n    + coalesce(p.studio_expenses, 0::numeric) as coach_and_studio_expenses,\n  coalesce(c.content_expenses, 0::numeric) as content_expenses\nfrom months m\nleft join pnl p on p.month = m.month\nleft join acquiring a on a.month = m.month\nleft join expenses e on e.month = m.month\nleft join content c on c.month = m.month\norder by m.month desc;"}	monthly_pnl_view_exclude_reversed_entries	ov.shatvoryan@gmail.com	\N	\N
20260709134657	{"alter table public.client_notification_events\n  add column if not exists attempt_count integer not null default 0;\n\nalter table public.client_notification_events\n  add column if not exists last_attempt_at timestamptz;\n\nalter table public.client_notification_events\n  add column if not exists next_attempt_at timestamptz;\n\nalter table public.client_notification_events\n  add column if not exists last_alerted_at timestamptz;\n\ncreate or replace function public.enqueue_client_notification_event(\n  p_client_id uuid,\n  p_event_type text,\n  p_source_table text default null::text,\n  p_source_id text default null::text,\n  p_recipient_type text default 'client'::text,\n  p_channel text default 'telegram'::text,\n  p_payload jsonb default '{}'::jsonb\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path to 'public', 'extensions', 'net', 'vault'\nas $function$\ndeclare\n  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);\n  v_payload_hash text;\n  v_event_id uuid;\n  v_event_status text;\n  v_request_id bigint;\n  v_function_url text;\n  v_secret text;\nbegin\n  v_payload_hash := encode(\n    digest(\n      coalesce(p_event_type, '') || '|' ||\n      coalesce(p_source_table, '') || '|' ||\n      coalesce(p_source_id, '') || '|' ||\n      coalesce(p_recipient_type, '') || '|' ||\n      coalesce(p_channel, '') || '|' ||\n      v_payload::text,\n      'sha256'\n    ),\n    'hex'\n  );\n\n  insert into public.client_notification_events (\n    client_id,\n    event_type,\n    source_table,\n    source_id,\n    recipient_type,\n    channel,\n    status,\n    payload_hash,\n    payload,\n    attempt_count,\n    next_attempt_at\n  )\n  values (\n    p_client_id,\n    p_event_type,\n    p_source_table,\n    p_source_id,\n    p_recipient_type,\n    p_channel,\n    'pending',\n    v_payload_hash,\n    v_payload,\n    0,\n    now()\n  )\n  on conflict (\n    event_type,\n    coalesce(source_table, ''),\n    coalesce(source_id, ''),\n    recipient_type,\n    channel,\n    payload_hash\n  )\n  do update\n  set\n    updated_at = now(),\n    next_attempt_at = case\n      when client_notification_events.status in ('sent', 'skipped', 'failed')\n        then client_notification_events.next_attempt_at\n      else now()\n    end\n  returning id, status into v_event_id, v_event_status;\n\n  if v_event_status in ('sent', 'skipped', 'failed') then\n    return v_event_id;\n  end if;\n\n  begin\n    select decrypted_secret\n    into v_function_url\n    from vault.decrypted_secrets\n    where name = 'CLIENT_NOTIFICATIONS_ENGINE_URL'\n    limit 1;\n\n    select decrypted_secret\n    into v_secret\n    from vault.decrypted_secrets\n    where name = 'NOTIFICATIONS_INTERNAL_SECRET'\n    limit 1;\n\n    if v_function_url is null or v_secret is null then\n      update public.client_notification_events\n      set\n        status = 'failed',\n        error_code = 'notification_config_missing',\n        error_message = 'CLIENT_NOTIFICATIONS_ENGINE_URL or NOTIFICATIONS_INTERNAL_SECRET is missing',\n        updated_at = now()\n      where id = v_event_id\n        and status not in ('sent', 'skipped', 'failed');\n\n      raise warning 'notification Edge Function config missing in Vault for event %', v_event_id;\n      return v_event_id;\n    end if;\n\n    select net.http_post(\n      url := v_function_url,\n      body := jsonb_build_object('eventId', v_event_id),\n      params := '{}'::jsonb,\n      headers := jsonb_build_object(\n        'content-type', 'application/json',\n        'x-notifications-secret', v_secret\n      ),\n      timeout_milliseconds := 20000\n    )\n    into v_request_id;\n\n  exception\n    when others then\n      update public.client_notification_events\n      set\n        status = 'failed',\n        error_code = 'notification_edge_invoke_failed',\n        error_message = left(sqlerrm, 500),\n        updated_at = now()\n      where id = v_event_id\n        and status not in ('sent', 'skipped', 'failed');\n\n      raise warning 'notification edge invoke failed for event %, error: %', v_event_id, sqlerrm;\n  end;\n\n  return v_event_id;\n\nexception\n  when others then\n    raise warning 'enqueue_client_notification_event failed: %', sqlerrm;\n    return null;\nend;\n$function$;\n\ndo $$\nbegin\n  begin\n    perform cron.unschedule('client_notifications_stale_finalizer');\n  exception\n    when others then\n      null;\n  end;\n\n  perform cron.schedule(\n    'client_notifications_stale_finalizer',\n    '*/5 * * * *',\n    $cron$\n    select net.http_post(\n      url := (\n        select decrypted_secret\n        from vault.decrypted_secrets\n        where name = 'CLIENT_NOTIFICATIONS_ENGINE_URL'\n        limit 1\n      ),\n      body := jsonb_build_object('mode', 'finalize_stale'),\n      params := '{}'::jsonb,\n      headers := jsonb_build_object(\n        'content-type', 'application/json',\n        'x-notifications-secret', (\n          select decrypted_secret\n          from vault.decrypted_secrets\n          where name = 'NOTIFICATIONS_INTERNAL_SECRET'\n          limit 1\n        )\n      ),\n      timeout_milliseconds := 20000\n    );\n    $cron$\n  );\nend $$;"}	notification_retry_alerts	ov.shatvoryan@gmail.com	\N	\N
20260709154928	{"alter table public.coach_profiles\n  add column if not exists telegram_id text;"}	coach_profiles_telegram_id	ov.shatvoryan@gmail.com	\N	\N
20260709193707	{"do $migration$\ndeclare\n  v_sql text;\n  v_old_deposit_tag_logic text := $old$\n  elsif v_is_deposit then\n    v_client_tag := 'deposit';$old$;\n  v_new_deposit_tag_logic text := $new$\n  elsif v_is_deposit then\n    v_client_tag := coalesce(nullif(trim(coalesce(v_existing_client.tag, '')), ''), 'deposit');$new$;\nbegin\n  select pg_get_functiondef('public.process_paid_purchase(uuid)'::regprocedure)\n    into v_sql;\n\n  if v_sql is null then\n    raise exception 'process_paid_purchase(uuid) does not exist';\n  end if;\n\n  if position('v_base_ds := 1100;' in v_sql) = 0 then\n    raise exception 'Expected old RUB ds fallback was not found in process_paid_purchase';\n  end if;\n\n  if position(v_old_deposit_tag_logic in v_sql) = 0 then\n    raise exception 'Expected old deposit tag logic was not found in process_paid_purchase';\n  end if;\n\n  v_sql := replace(v_sql, 'v_base_ds := 1100;', 'v_base_ds := 800;');\n  v_sql := replace(v_sql, v_old_deposit_tag_logic, v_new_deposit_tag_logic);\n\n  execute v_sql;\nend;\n$migration$;"}	purchase_price_deposit_tag	ov.shatvoryan@gmail.com	\N	\N
20260710083320	{"create or replace function public.sync_client_coach_link(p_client_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_client public.clients%rowtype;\n  v_coach_handle text;\n  v_coach_id uuid;\n  v_deactivated_count integer := 0;\nbegin\n  select *\n    into v_client\n  from public.clients\n  where id = p_client_id;\n\n  if not found then\n    return jsonb_build_object('ok', false, 'error', 'client_not_found');\n  end if;\n\n  v_coach_handle := nullif(trim(coalesce(v_client.coach, '')), '');\n\n  if v_coach_handle is null or v_coach_handle ilike '%wr_off%' then\n    update public.coach_clients\n    set\n      is_active = false,\n      updated_at = now()\n    where client_id = p_client_id\n      and is_active = true;\n\n    get diagnostics v_deactivated_count = row_count;\n\n    return jsonb_build_object(\n      'ok', true,\n      'action', 'deactivated',\n      'reason', case when v_coach_handle is null then 'empty_coach' else 'wr_off' end,\n      'deactivated_count', v_deactivated_count\n    );\n  end if;\n\n  select id\n    into v_coach_id\n  from public.coach_profiles\n  where lower(coach_name) = lower(v_coach_handle)\n    and is_active = true\n  order by created_at\n  limit 1;\n\n  if v_coach_id is null then\n    return jsonb_build_object(\n      'ok', false,\n      'error', 'coach_profile_not_found',\n      'coach', v_coach_handle\n    );\n  end if;\n\n  update public.coach_clients\n  set\n    is_active = false,\n    updated_at = now()\n  where client_id = p_client_id\n    and coach_id <> v_coach_id\n    and is_active = true;\n\n  get diagnostics v_deactivated_count = row_count;\n\n  insert into public.coach_clients (\n    coach_id,\n    client_id,\n    is_active,\n    created_at,\n    updated_at\n  )\n  values (\n    v_coach_id,\n    p_client_id,\n    true,\n    now(),\n    now()\n  )\n  on conflict (coach_id, client_id)\n  do update\n  set\n    is_active = true,\n    updated_at = now();\n\n  return jsonb_build_object(\n    'ok', true,\n    'action', 'linked',\n    'coach_id', v_coach_id,\n    'coach', v_coach_handle,\n    'deactivated_count', v_deactivated_count\n  );\nend;\n$function$;\n\ndo $migration$\ndeclare\n  v_sql text;\n  v_anchor text := $anchor$  insert into client_transactions ($anchor$;\n  v_replacement text := $replacement$  perform public.sync_client_coach_link(v_client_id);\n\n  insert into client_transactions ($replacement$;\nbegin\n  select pg_get_functiondef('public.process_paid_purchase(uuid)'::regprocedure)\n    into v_sql;\n\n  if v_sql is null then\n    raise exception 'process_paid_purchase(uuid) does not exist';\n  end if;\n\n  if position('perform public.sync_client_coach_link(v_client_id);' in lower(v_sql)) > 0 then\n    raise notice 'process_paid_purchase already calls sync_client_coach_link';\n    return;\n  end if;\n\n  if position(v_anchor in v_sql) = 0 then\n    raise exception 'Expected process_paid_purchase transaction anchor was not found';\n  end if;\n\n  v_sql := replace(v_sql, v_anchor, v_replacement);\n\n  execute v_sql;\nend;\n$migration$;\n\nupdate public.coach_clients cc\nset\n  is_active = false,\n  updated_at = now()\nfrom public.clients c\nwhere cc.client_id = c.id\n  and cc.is_active = true\n  and (\n    nullif(trim(coalesce(c.coach, '')), '') is null\n    or c.coach ilike '%wr_off%'\n  );\n\nwith matched_clients as (\n  select\n    c.id as client_id,\n    cp.id as coach_id\n  from public.clients c\n  join public.coach_profiles cp\n    on lower(cp.coach_name) = lower(trim(c.coach))\n   and cp.is_active = true\n  where nullif(trim(coalesce(c.coach, '')), '') is not null\n    and c.coach not ilike '%wr_off%'\n),\nupserted as (\n  insert into public.coach_clients (\n    coach_id,\n    client_id,\n    is_active,\n    created_at,\n    updated_at\n  )\n  select\n    coach_id,\n    client_id,\n    true,\n    now(),\n    now()\n  from matched_clients\n  on conflict (coach_id, client_id)\n  do update\n  set\n    is_active = true,\n    updated_at = now()\n  returning client_id, coach_id\n)\nupdate public.coach_clients cc\nset\n  is_active = false,\n  updated_at = now()\nfrom upserted u\nwhere cc.client_id = u.client_id\n  and cc.coach_id <> u.coach_id\n  and cc.is_active = true;"}	sync_coach_links	ov.shatvoryan@gmail.com	\N	\N
20260710110655	{"alter table public.n8n_webhook_logs\n  add column if not exists attempt_count integer not null default 1,\n  add column if not exists delivery_status text,\n  add column if not exists error_code text;\n\ncreate or replace function public.reliability_monitor_pg_net_failure_summary(\n  p_since timestamptz,\n  p_limit integer default 10\n)\nreturns table(\n  failure_count bigint,\n  sample_ids bigint[],\n  sample_status_codes integer[],\n  sample_errors text[]\n)\nlanguage sql\nsecurity definer\nset search_path = public, net\nas $function$\n  with failures as (\n    select\n      id,\n      status_code,\n      timed_out,\n      left(coalesce(error_msg, ''), 300) as safe_error_msg,\n      created\n    from net._http_response\n    where created >= p_since\n      and (\n        coalesce(status_code, 0) >= 400\n        or timed_out is true\n        or error_msg is not null\n      )\n    order by created desc\n  ),\n  limited as (\n    select *\n    from failures\n    limit greatest(least(coalesce(p_limit, 10), 50), 0)\n  )\n  select\n    (select count(*) from failures) as failure_count,\n    coalesce(array_agg(id order by created desc), '{}'::bigint[]) as sample_ids,\n    coalesce(array_agg(status_code order by created desc), '{}'::integer[]) as sample_status_codes,\n    coalesce(array_agg(\n      nullif(\n        concat_ws(\n          ' ',\n          case when timed_out then 'timed_out' else null end,\n          safe_error_msg\n        ),\n        ''\n      )\n      order by created desc\n    ), '{}'::text[]) as sample_errors\n  from limited;\n$function$;\n\ncreate or replace function public.reliability_monitor_cron_job_status()\nreturns table(\n  jobname text,\n  schedule text,\n  active boolean,\n  job_exists boolean\n)\nlanguage sql\nsecurity definer\nset search_path = public, cron\nas $function$\n  with expected(jobname) as (\n    values\n      ('process-coach-acts-daily'::text),\n      ('process-expired-clients-daily'::text),\n      ('update_exchange_rates_daily'::text)\n  )\n  select\n    expected.jobname,\n    cron.job.schedule,\n    cron.job.active,\n    cron.job.jobid is not null as job_exists\n  from expected\n  left join cron.job\n    on cron.job.jobname = expected.jobname\n  order by expected.jobname;\n$function$;\n\ngrant execute on function public.reliability_monitor_pg_net_failure_summary(timestamptz, integer) to service_role;\ngrant execute on function public.reliability_monitor_cron_job_status() to service_role;\n\ndo $migration$\ndeclare\n  v_project_url text := 'https://ahmwnchujgenbkpjyxdz.supabase.co';\n  v_secret_name text := 'cron_edge_function_bearer';\n  v_existing_bearer text;\n  v_secret_id uuid;\n  v_job record;\n  v_existing_job record;\n  v_command text;\nbegin\n  select (regexp_match(command, $re$Bearer ([^\\"'}]+)$re$))[1]\n    into v_existing_bearer\n  from cron.job\n  where jobname in (\n    'process-coach-acts-daily',\n    'process-expired-clients-daily',\n    'update_exchange_rates_daily'\n  )\n    and command like '%Bearer %'\n  limit 1;\n\n  select id\n    into v_secret_id\n  from vault.secrets\n  where name = v_secret_name;\n\n  if v_secret_id is null and nullif(v_existing_bearer, '') is null then\n    raise exception 'Vault secret % is missing and no existing cron bearer could be extracted', v_secret_name;\n  end if;\n\n  if nullif(v_existing_bearer, '') is not null then\n    if v_secret_id is null then\n      perform vault.create_secret(\n        v_existing_bearer,\n        v_secret_name,\n        'Bearer token for pg_cron Edge Function invocations',\n        null\n      );\n    else\n      perform vault.update_secret(\n        v_secret_id,\n        v_existing_bearer,\n        v_secret_name,\n        'Bearer token for pg_cron Edge Function invocations',\n        null\n      );\n    end if;\n  end if;\n\n  for v_job in\n    select *\n    from (\n      values\n        ('process-coach-acts-daily'::text, 'process-coach-acts-daily'::text),\n        ('process-expired-clients-daily'::text, 'process-expired-clients-daily'::text),\n        ('update_exchange_rates_daily'::text, 'update-exchange-rates'::text)\n    ) as target(jobname, function_slug)\n  loop\n    select format(\n      $cmd$select\n  net.http_post(\n      url := %L,\n      headers := jsonb_build_object(\n        'Content-Type', 'application/json',\n        'Authorization', 'Bearer ' || (\n          select secret\n          from vault.decrypted_secrets\n          where name = %L\n          limit 1\n        )\n      ),\n      body := '{}'::jsonb,\n      timeout_milliseconds := 20000\n  );$cmd$,\n      v_project_url || '/functions/v1/' || v_job.function_slug,\n      v_secret_name\n    ) into v_command;\n\n    select *\n      into v_existing_job\n    from cron.job\n    where jobname = v_job.jobname;\n\n    if not found then\n      raise exception 'Expected cron job % was not found', v_job.jobname;\n    end if;\n\n    perform cron.alter_job(\n      job_id := v_existing_job.jobid,\n      command := v_command\n    );\n  end loop;\n\n  select format(\n    $cmd$select\n  net.http_post(\n      url := %L,\n      headers := jsonb_build_object(\n        'Content-Type', 'application/json',\n        'Authorization', 'Bearer ' || (\n          select secret\n          from vault.decrypted_secrets\n          where name = %L\n          limit 1\n        )\n      ),\n      body := '{}'::jsonb,\n      timeout_milliseconds := 20000\n  );$cmd$,\n    v_project_url || '/functions/v1/hourly-reliability-monitor',\n    v_secret_name\n  ) into v_command;\n\n  if exists (select 1 from cron.job where jobname = 'hourly-reliability-monitor') then\n    select *\n      into v_existing_job\n    from cron.job\n    where jobname = 'hourly-reliability-monitor';\n\n    perform cron.alter_job(\n      job_id := v_existing_job.jobid,\n      schedule := '0 * * * *',\n      command := v_command,\n      active := true\n    );\n  else\n    perform cron.schedule(\n      'hourly-reliability-monitor',\n      '0 * * * *',\n      v_command\n    );\n  end if;\nend;\n$migration$;"}	cron_edge_reliability	ov.shatvoryan@gmail.com	\N	\N
20260712103108	{"-- Keep pg_cron -> pg_net Edge Function invocations resilient to copied bearer\n-- values with newlines or other whitespace/control characters.\ndo $migration$\ndeclare\n  v_project_url text := 'https://ahmwnchujgenbkpjyxdz.supabase.co';\n  v_secret_name text := 'cron_edge_function_bearer';\n  v_secret_id uuid;\n  v_clean_bearer text;\n  v_job record;\n  v_existing_job record;\n  v_command text;\nbegin\n  select id\n    into v_secret_id\n  from vault.secrets\n  where name = v_secret_name;\n\n  if v_secret_id is null then\n    raise exception 'Vault secret % is missing', v_secret_name;\n  end if;\n\n  select nullif(\n    regexp_replace(\n      regexp_replace(coalesce(secret, ''), '[[:cntrl:]]', '', 'g'),\n      '\\\\s+',\n      '',\n      'g'\n    ),\n    ''\n  )\n    into v_clean_bearer\n  from vault.decrypted_secrets\n  where name = v_secret_name\n  limit 1;\n\n  if v_clean_bearer is null then\n    raise exception 'Vault secret % is empty after sanitization', v_secret_name;\n  end if;\n\n  if lower(left(v_clean_bearer, 7)) = 'bearer ' then\n    v_clean_bearer := nullif(trim(substr(v_clean_bearer, 8)), '');\n  end if;\n\n  if v_clean_bearer is null then\n    raise exception 'Vault secret % contains only an authorization prefix', v_secret_name;\n  end if;\n\n  perform vault.update_secret(\n    v_secret_id,\n    v_clean_bearer,\n    v_secret_name,\n    'Bearer token for pg_cron Edge Function invocations',\n    null\n  );\n\n  for v_job in\n    select *\n    from (\n      values\n        ('process-coach-acts-daily'::text, 'process-coach-acts-daily'::text, '0 7 * * *'::text),\n        ('process-expired-clients-daily'::text, 'process-expired-clients-daily'::text, '0 7 * * *'::text),\n        ('update_exchange_rates_daily'::text, 'update-exchange-rates'::text, '0 6 * * *'::text),\n        ('hourly-reliability-monitor'::text, 'hourly-reliability-monitor'::text, '0 * * * *'::text)\n    ) as target(jobname, function_slug, schedule)\n  loop\n    select *\n      into v_existing_job\n    from cron.job\n    where jobname = v_job.jobname;\n\n    if not found then\n      raise exception 'Expected cron job % was not found', v_job.jobname;\n    end if;\n\n    select format(\n      $cmd$select\n  net.http_post(\n      url := %L,\n      headers := jsonb_build_object(\n        'Content-Type', 'application/json',\n        'Authorization', 'Bearer ' || (\n          select nullif(\n            regexp_replace(\n              regexp_replace(coalesce(secret, ''), '[[:cntrl:]]', '', 'g'),\n              '\\\\s+',\n              '',\n              'g'\n            ),\n            ''\n          )\n          from vault.decrypted_secrets\n          where name = %L\n          limit 1\n        )\n      ),\n      body := '{}'::jsonb,\n      timeout_milliseconds := 20000\n  );$cmd$,\n      v_project_url || '/functions/v1/' || v_job.function_slug,\n      v_secret_name\n    ) into v_command;\n\n    perform cron.alter_job(\n      job_id := v_existing_job.jobid,\n      schedule := v_job.schedule,\n      command := v_command,\n      active := true\n    );\n  end loop;\nend;\n$migration$;"}	sanitize_cron_edge_bearer	ov.shatvoryan@gmail.com	\N	\N
20260712103222	{"-- The previous cron reliability migration moved Edge Function bearer lookup to\n-- Vault, but cron commands must read vault.decrypted_secrets.decrypted_secret\n-- rather than the encrypted storage column.\ndo $migration$\ndeclare\n  v_project_url text := 'https://ahmwnchujgenbkpjyxdz.supabase.co';\n  v_secret_name text := 'cron_edge_function_bearer';\n  v_secret_id uuid;\n  v_recovered_bearer text;\n  v_job record;\n  v_existing_job record;\n  v_command text;\nbegin\n  select id\n    into v_secret_id\n  from vault.secrets\n  where name = v_secret_name;\n\n  if v_secret_id is null then\n    raise exception 'Vault secret % is missing', v_secret_name;\n  end if;\n\n  select nullif(\n    regexp_replace(\n      regexp_replace((regexp_match(command, $re$Bearer ([^'\\"}[:space:]]+)$re$))[1], '[[:cntrl:]]', '', 'g'),\n      '\\\\s+',\n      '',\n      'g'\n    ),\n    ''\n  )\n    into v_recovered_bearer\n  from cron.job_run_details\n  where command like '%Authorization%Bearer %'\n    and command not like '%vault.decrypted_secrets%'\n    and jobid in (1, 2, 3, 6)\n    and (regexp_match(command, $re$Bearer ([^'\\"}[:space:]]+)$re$))[1] is not null\n  order by start_time desc\n  limit 1;\n\n  if v_recovered_bearer is null then\n    select nullif(\n      regexp_replace(\n        regexp_replace(coalesce(decrypted_secret, ''), '[[:cntrl:]]', '', 'g'),\n        '\\\\s+',\n        '',\n        'g'\n      ),\n      ''\n    )\n      into v_recovered_bearer\n    from vault.decrypted_secrets\n    where name = v_secret_name\n    limit 1;\n  end if;\n\n  if v_recovered_bearer is null then\n    raise exception 'No usable bearer found for %', v_secret_name;\n  end if;\n\n  if lower(left(v_recovered_bearer, 7)) = 'bearer ' then\n    v_recovered_bearer := nullif(trim(substr(v_recovered_bearer, 8)), '');\n  end if;\n\n  if v_recovered_bearer is null then\n    raise exception 'Recovered bearer for % contains only an authorization prefix', v_secret_name;\n  end if;\n\n  perform vault.update_secret(\n    v_secret_id,\n    v_recovered_bearer,\n    v_secret_name,\n    'Bearer token for pg_cron Edge Function invocations',\n    null\n  );\n\n  for v_job in\n    select *\n    from (\n      values\n        ('process-coach-acts-daily'::text, 'process-coach-acts-daily'::text, '0 7 * * *'::text),\n        ('process-expired-clients-daily'::text, 'process-expired-clients-daily'::text, '0 7 * * *'::text),\n        ('update_exchange_rates_daily'::text, 'update-exchange-rates'::text, '0 6 * * *'::text),\n        ('hourly-reliability-monitor'::text, 'hourly-reliability-monitor'::text, '0 * * * *'::text)\n    ) as target(jobname, function_slug, schedule)\n  loop\n    select *\n      into v_existing_job\n    from cron.job\n    where jobname = v_job.jobname;\n\n    if not found then\n      raise exception 'Expected cron job % was not found', v_job.jobname;\n    end if;\n\n    select format(\n      $cmd$select\n  net.http_post(\n      url := %L,\n      headers := jsonb_build_object(\n        'Content-Type', 'application/json',\n        'Authorization', 'Bearer ' || (\n          select nullif(\n            regexp_replace(\n              regexp_replace(coalesce(decrypted_secret, ''), '[[:cntrl:]]', '', 'g'),\n              '\\\\s+',\n              '',\n              'g'\n            ),\n            ''\n          )\n          from vault.decrypted_secrets\n          where name = %L\n          limit 1\n        )\n      ),\n      body := '{}'::jsonb,\n      timeout_milliseconds := 20000\n  );$cmd$,\n      v_project_url || '/functions/v1/' || v_job.function_slug,\n      v_secret_name\n    ) into v_command;\n\n    perform cron.alter_job(\n      job_id := v_existing_job.jobid,\n      schedule := v_job.schedule,\n      command := v_command,\n      active := true\n    );\n  end loop;\nend;\n$migration$;"}	recover_cron_edge_bearer_plaintext	ov.shatvoryan@gmail.com	\N	\N
20260712115146	{"alter table public.coach_clients\n  add column if not exists last_program_template_id uuid;\n\ndo $$\nbegin\n  if not exists (\n    select 1\n    from pg_constraint\n    where conrelid = 'public.coach_clients'::regclass\n      and conname = 'coach_clients_last_program_template_id_fkey'\n  ) then\n    alter table public.coach_clients\n      add constraint coach_clients_last_program_template_id_fkey\n      foreign key (last_program_template_id)\n      references public.program_templates(id)\n      on delete set null;\n  end if;\nend;\n$$;\n\ncreate index if not exists idx_coach_clients_last_program_template_id\n  on public.coach_clients(last_program_template_id)\n  where last_program_template_id is not null;"}	coach_client_last_program_template	ov.shatvoryan@gmail.com	\N	\N
20260713132041	{"do $migration$\ndeclare\n  v_sql text;\n  v_old_coach_assignment text := '      coach = coalesce(v_coach, clients.coach),';\n  v_new_coach_assignment text := '      coach = clients.coach,';\n  v_old_coach_link_guard text := '  if v_coach is not null then';\n  v_new_coach_link_guard text := '  if v_existing_client.id is null and v_coach is not null then';\nbegin\n  select pg_get_functiondef('public.process_paid_purchase(uuid)'::regprocedure)\n    into v_sql;\n\n  if v_sql is null then\n    raise exception 'process_paid_purchase(uuid) does not exist';\n  end if;\n\n  if position(v_new_coach_assignment in v_sql) > 0\n     and position(v_new_coach_link_guard in v_sql) > 0 then\n    raise notice 'process_paid_purchase already preserves first-purchase coach';\n    return;\n  end if;\n\n  if position(v_old_coach_assignment in v_sql) = 0 then\n    raise exception 'Expected existing-client coach assignment was not found in process_paid_purchase';\n  end if;\n\n  if position(v_old_coach_link_guard in v_sql) = 0 then\n    raise exception 'Expected purchase-derived coach_clients guard was not found in process_paid_purchase';\n  end if;\n\n  v_sql := replace(v_sql, v_old_coach_assignment, v_new_coach_assignment);\n  v_sql := replace(v_sql, v_old_coach_link_guard, v_new_coach_link_guard);\n\n  if position(v_new_coach_assignment in v_sql) = 0 then\n    raise exception 'process_paid_purchase coach assignment patch failed';\n  end if;\n\n  if position(v_new_coach_link_guard in v_sql) = 0 then\n    raise exception 'process_paid_purchase coach_clients guard patch failed';\n  end if;\n\n  execute v_sql;\nend;\n$migration$;"}	preserve_first_purchase_coach	ov.shatvoryan@gmail.com	\N	\N
20260729100500	{"create or replace function public.get_daily_student_metrics_report()\nreturns jsonb\nlanguage sql\nstable\nsecurity invoker\nset search_path = public, pg_temp\nas $function$\n  with base as (\n    select\n      tag,\n      coalesce(first_fact, 0) as first_fact,\n      last_fact\n    from public.clients\n    where is_active is true\n  ),\n  active_students as (\n    select *\n    from base\n    where last_fact >= current_date - 21\n      and first_fact >= 2\n  ),\n  passed_trial as (\n    select *\n    from base\n    where last_fact >= current_date - 21\n      and first_fact = 1\n  ),\n  bought_trial as (\n    select *\n    from base\n    where first_fact = 0\n  )\n  select jsonb_build_object(\n    'active_total', (select count(*) from active_students),\n    'active_online', (\n      select count(*)\n      from active_students\n      where coalesce(tag, '') ilike '%ds%'\n    ),\n    'active_offline', (\n      select count(*)\n      from active_students\n      where coalesce(tag, '') not ilike '%ds%'\n    ),\n    'classic', (\n      select count(*)\n      from active_students\n      where coalesce(tag, '') ilike '%ds%'\n        and coalesce(tag, '') ilike '%classic%'\n    ),\n    'light', (\n      select count(*)\n      from active_students\n      where coalesce(tag, '') ilike '%ds%'\n        and coalesce(tag, '') ilike '%light%'\n    ),\n    'pullups', (\n      select count(*)\n      from active_students\n      where coalesce(tag, '') ilike '%ds%'\n        and coalesce(tag, '') ilike '%pullups%'\n    ),\n    'handstand', (\n      select count(*)\n      from active_students\n      where coalesce(tag, '') ilike '%ds%'\n        and coalesce(tag, '') ilike '%handstand%'\n    ),\n    'trial_passed', (select count(*) from passed_trial),\n    'trial_bought', (select count(*) from bought_trial),\n    'trial_bought_online', (\n      select count(*)\n      from bought_trial\n      where coalesce(tag, '') ilike '%ds%'\n    ),\n    'trial_bought_offline', (\n      select count(*)\n      from bought_trial\n      where coalesce(tag, '') not ilike '%ds%'\n    )\n  );\n$function$","revoke execute\non function public.get_daily_student_metrics_report()\nfrom public, anon, authenticated","grant execute\non function public.get_daily_student_metrics_report()\nto service_role","do $migration$\ndeclare\n  v_project_url text := 'https://ahmwnchujgenbkpjyxdz.supabase.co';\n  v_secret_name text := 'cron_edge_function_bearer';\n  v_command text;\nbegin\n  if exists (\n    select 1\n    from cron.job\n    where jobname = 'daily-metrics-report'\n  ) then\n    perform cron.unschedule('daily-metrics-report');\n  end if;\n\n  select format(\n    $cmd$select\n  net.http_post(\n      url := %L,\n      headers := jsonb_build_object(\n        'Content-Type', 'application/json',\n        'Authorization', 'Bearer ' || (\n          select secret\n          from vault.decrypted_secrets\n          where name = %L\n          limit 1\n        )\n      ),\n      body := '{}'::jsonb,\n      timeout_milliseconds := 20000\n  );$cmd$,\n    v_project_url || '/functions/v1/daily-metrics-report',\n    v_secret_name\n  ) into v_command;\n\n  perform cron.schedule(\n    'daily-metrics-report',\n    '0 6 * * *',\n    v_command\n  );\nend;\n$migration$"}	daily_metrics_report	\N	\N	\N
